// Package libgo is the library of Go parsers generated by zp gen.
//
// A generated parser imports this package as rt, or carries a copy of its files in its
// internal/libgo directory, so that it depends only on zeroparse.dev/zp/core (with
// core/noderep) and the standard library. The code generated from a grammar sets up the rules and
// calls the exported names that are documented as for generated parsers; those are not a stable
// API. The file api.go of the generated parser re-exports the names its users need. Its behavior
// must match internal/engine exactly; the generator tests in internal/engine compare them.
package libgo

import (
	"context"
	"fmt"
	"math"
	"sort"
	"strings"
	"sync"
	"unicode/utf8"

	"zeroparse.dev/zp/core"
	"zeroparse.dev/zp/core/noderep"
)

// isNode reports whether n is a node of the value model (a string node, a tuple or list node, or
// an error value) rather than a struct, a box or a list or tuple value.
func isNode(n *core.Node) bool {
	if k := D(n).Kind; k != nil && k.Base >= 0 && k.Base <= noderep.BaseError {
		return true
	}
	return D(n).Terminal
}

// UnboxNode returns the value that the carrier n stands for: the box's value for a box, nil for
// nil, and n otherwise.
//
// UnboxNode is for generated parsers; not a stable API.
func UnboxNode(n *core.Node) any {
	if n == nil {
		return nil
	}
	if D(n).Kind == noderep.BoxKind {
		return D(n).Box
	}
	return n
}

// UnboxValue is UnboxNode for a value that may be a carrier.
//
// UnboxValue is for generated parsers; not a stable API.
func UnboxValue(v any) any {
	if n, ok := v.(*core.Node); ok {
		return UnboxNode(n)
	}
	return v
}

// nodeValue returns the Value of the node n: its text for a string node, and a tuple or list
// value sharing its elements otherwise.
func (p *Parser) nodeValue(n *core.Node) any {
	switch {
	case D(n).Terminal:
		return D(n).Text
	case D(n).Kind != nil && D(n).Kind.Base == noderep.BaseList:
		return p.NewNode(Data{Kind: noderep.ListValueKind, Start: D(n).Start, End: D(n).End, Children: D(n).Children})
	}
	return p.NewNode(Data{Kind: noderep.TupleValueKind, Start: D(n).Start, End: D(n).End, Children: D(n).Children})
}

// KindOf returns the interned kind of the type and rule names (rules and actions prepare theirs).
//
// KindOf is for generated parsers; not a stable API.
func KindOf(typ, rule string) *noderep.Kind { return noderep.KindOf(typ, rule) }

// nodeTypeKinds are the kinds of the nodes of a named node type, by the base (BaseString,
// noderep.BaseTuple, noderep.BaseList) of the node converted to it. They have no rule.
type nodeTypeKinds [noderep.BaseList + 1]*noderep.Kind

// NewNodeTypeKinds returns the interned kinds of the named node type typ.
//
// NewNodeTypeKinds is for generated parsers; not a stable API.
func NewNodeTypeKinds(typ string) *nodeTypeKinds {
	var ks nodeTypeKinds
	for base := range ks {
		ks[base] = noderep.NodeTypeKind(typ, base)
	}
	return &ks
}

// convert returns the node of the named node type of ks that the value v converts to: a copy of
// v with the same range and content, or v itself if it already has the type. It reports false if
// v is not a string, tuple or list node.
func (ks *nodeTypeKinds) convert(v any) (*core.Node, bool) {
	n, ok := nodeOf(v)
	if !ok || !hasBase(n) {
		return nil, false
	}
	return ks.retype(n), true
}

// hasBase reports whether n is a string, tuple or list node, of a named node type or not: a node
// that a conversion converts. It is the operation node.hasBase.
func hasBase(n *core.Node) bool {
	return D(n).Kind != nil && D(n).Kind.Base >= 0 && D(n).Kind.Base <= noderep.BaseList
}

// retype returns n, a string, tuple or list node, as a node of the named node type of ks: a copy of
// n with the same range and content, or n itself if it already has the type. It is the operation
// node.convert.
func (ks *nodeTypeKinds) retype(n *core.Node) *core.Node {
	k := ks[D(n).Kind.Base]
	if D(n).Kind == k {
		return n
	}
	c := *D(n)
	c.Kind, c.Fresh = k, false
	if D(n).Fresh {
		// The rule that made n may still change it; the copy keeps what it holds now.
		c.Children = append([]*core.Node(nil), D(n).Children...)
	}
	c.Fields = append(noderep.Fields(nil), D(n).Fields...)
	return nodeOfData(&c)
}

// convertOwned gives n, a node that nothing else holds, the named node type of ks in place. It
// reports false if n is not a string, tuple or list node.
func (ks *nodeTypeKinds) convertOwned(n *core.Node) bool {
	if n == nil || !hasBase(n) {
		return false
	}
	D(n).Kind = ks[D(n).Kind.Base]
	return true
}

// BaseNode returns the node n of a named node type as the string, tuple or list node it was
// converted from: a copy with the kind of that node (n itself for other nodes).
func BaseNode(n *core.Node) *core.Node {
	if !D(n).Kind.IsNodeType() {
		return n
	}
	c := *D(n)
	c.Kind = baseKinds[D(n).Kind.Base]
	return nodeOfData(&c)
}

// TermNodeType returns the named node type typ, the operand of TermConvert.
//
// TermNodeType is for generated parsers; not a stable API.
func (p *Parser) TermNodeType(typ string) *nodeTypeKinds { return p.g.NodeTypes[typ] }

// RawField returns the value of the field or capture name, whether or not it is public.
func RawField(n *core.Node, name string) any {
	if n == nil {
		return nil
	}
	v, _ := D(n).Fields.Get(name)
	return v
}

// valueTypeName names the type of a value of the given shape in messages, in the terms of the
// value model: node[string] for a string node, node[(_, _)] and node[[]_] for tuple and list
// nodes (a tuple has elems elements), error for an error value, (_, _) and []_ for tuple and list
// values, and name for a struct.
func valueTypeName(shape noderep.Shape, name string, elems int) string {
	switch shape {
	case noderep.ShapeString:
		return "node[string]"
	case noderep.ShapeTuple:
		return "node[" + tupleTerm(elems) + "]"
	case noderep.ShapeList:
		return "node[[]_]"
	case noderep.ShapeError:
		return "error"
	case noderep.ShapeTupleValue:
		return tupleTerm(elems)
	case noderep.ShapeListValue:
		return "[]_"
	}
	return name
}

// tupleTerm is the type term of a tuple of n elements of unknown types.
func tupleTerm(n int) string {
	if n == 1 {
		return "(_,)"
	}
	return "(" + strings.TrimSuffix(strings.Repeat("_, ", n), ", ") + ")"
}

// --- Rules ---

// Rule is for generated parsers; not a stable API.
type Rule struct {
	kinds noderep.RuleKinds // the node kinds the rule makes (set by setKinds)
	Id    int
	Name  string
	Scope []string // capture names of the rule body, in slot order
	Body  func(p *Parser, min int) (*core.Node, bool)
	// Action returns the value of the rule's action and the failure that ends its evaluation, nil if
	// it does not fail.
	Action func(c *ActCtx) (any, any)
	Value  Shaper // makes the rule's value from the value of its body, without an action
	// NodeType, if not "", is the named node type the rule's value is converted to, whose kinds
	// are nodeKinds.
	NodeType  string
	nodeKinds *nodeTypeKinds
	// OpNodeType, if not "", is the named node type every operator node of an Operators Rule is
	// converted to, whose kinds are opKinds.
	OpNodeType string
	opKinds    *nodeTypeKinds
	// Memo means the rule's results are memoized. It is false for transient rules, whose entries
	// could never be reused.
	Memo bool
	// Leader is the leader of a left-recursive cycle; its results are always memoized.
	Leader bool
	// Rec means the rule is on a cycle of calls: its entries count against the nesting limit.
	Rec bool
	// Cycle numbers the left-recursion cycle of a leader or a member of one from 1, and is 0 for
	// any other rule: a call of a rule of a cycle can read the seeds of the cycle's leaders that grow
	// at its position (context_memo.go).
	Cycle int32
	// leaderIndex numbers the leaders of each cycle from 0 (numberLeaders); the first maxLeaderBits
	// of a cycle have the bit 1<<leaderIndex in the present sets of its results.
	leaderIndex int32
	// DocMemo means Documents memoize the rule, transient or not, as the engine does for a leader
	// and for a rule marked for memoization.
	DocMemo bool
	// Positional means the rule's results may depend on positions (.Start, .End), not only on the
	// input they examine: an edit of a Document before them removes them instead of moving them.
	Positional bool
	// Seen is the rule's index among the memoized rules whose memoization is deferred to the
	// second call at a position (FirstCall), or -1.
	Seen          int
	OperatorsRule *OperatorsRule
	Novalue       bool // value-free twin, called where the value is discarded
	// Splice means the rule makes no node of its own: its value is the result of its body as it is,
	// and the captures of its body end with it. Its callers take the elements of the value.
	Splice bool
	// Where, if not "", names the rule in the message of a failed action, instead of Name: the
	// hidden rule of an inline action is named by the rule that holds the action.
	Where string
	// Vars are the variables the rule or its callees read, sorted. Memo entries are keyed by their
	// values at the call, since definitions inside the rule are undone when it returns.
	Vars []string
	// initVals are the initial values of Vars (grammar.SetVars), or nil when Vars is empty.
	initVals []any
	// varSlots are the slots of Vars (-1 for a name that no variable declares).
	varSlots []int
	g        *grammar // the grammar whose rule table holds the rule (grammar.SetRules)
}

// grammar holds the tables of one generated grammar. The generated code builds
// one for its rule table and, with Recognize, one for the recognizer's rule
// table, which shares the other tables. Every rule refers to its grammar.
//
// Of its fields and methods, Descs, NodeTypes, Observable, SetRules, Share, SourceInfo, StartError, StartRule, Starts, StructFields, TypeKinds are for generated parsers; not a stable API.
type grammar struct {
	// rules is the rule table and nseen the number of its rules with rule.Seen set.
	rules []*Rule
	nseen int
	// Starts holds the names of the start rules, the rules marked @start where parsing may
	// begin.
	Starts []string
	// DefaultStart is the default start rule, which an empty start rule name selects.
	DefaultStart string
	// Descs maps expectation IDs to their descriptions. It starts with the fixed expectations
	// below. A grammar without Expectations has none.
	Descs []string
	// Expectations reports that the parser was generated with the means to record expectations (the
	// Descs table). A parse records them only when it asks with WithExpectations; otherwise it records
	// the farthest failure position only.
	Expectations bool
	// StructFields holds the fields of each struct type (DeclareStruct).
	StructFields map[string]*structFields
	// TypeKinds holds the node kinds of the struct types.
	TypeKinds map[string]*noderep.Kind
	// NodeTypes holds the kinds of the grammar's named node types, also under the names of the
	// aliases of them.
	NodeTypes map[string]*nodeTypeKinds
	// SourceInfo reports that values record source information: the rule that produced each
	// node and where its captures are.
	SourceInfo bool
	// Observable reports that the parser was generated with observability: only then do the
	// trace and profile options take effect, so only then does ResolveOptions accept them.
	Observable bool
	// NoBudgetControls reports that the parser was generated without limit controls, so that a parse
	// asking for them fails.
	NoBudgetControls bool
	// MaxDepth is the default maximum nesting of recursive rule calls.
	maxDepth int
	// initEnv is the environment every parse starts from, with each variable bound to its
	// initial value. A variable's slot is its position in varNames, and envDepth is the depth of
	// the environment (envDepthOf the number of variables).
	initEnv  *Env
	varNames []string
	envDepth int
}

// SetVars makes the variables names, with the initial values vals, the starting environment of
// every parse.
//
// SetVars is for generated parsers; not a stable API.
func (g *grammar) SetVars(names []string, vals []any) {
	g.varNames = names
	g.envDepth = envDepthOf(len(vals))
	g.initEnv = newEnv(vals, g.envDepth)
	g.indexInitVals()
}

// indexInitVals computes the slots and the initial values of the variables each rule reads, so
// that the memo key of a call made before any binding shares the values instead of allocating.
// Names are resolved through a map when there are many variables, so that the cost is linear in
// the names the rules read.
func (g *grammar) indexInitVals() {
	var slotOf map[string]int
	if len(g.varNames) > 8 {
		slotOf = make(map[string]int, len(g.varNames))
		for slot, v := range g.varNames {
			slotOf[v] = slot
		}
	}
	for _, r := range g.rules {
		r.initVals, r.varSlots = nil, nil
		if len(r.Vars) == 0 {
			continue
		}
		r.initVals = make([]any, len(r.Vars))
		r.varSlots = make([]int, len(r.Vars))
		for i, name := range r.Vars {
			r.varSlots[i] = -1
			if slotOf != nil {
				if slot, ok := slotOf[name]; ok {
					r.varSlots[i] = slot
				}
			} else {
				for slot, v := range g.varNames {
					if v == name {
						r.varSlots[i] = slot
						break
					}
				}
			}
			if r.varSlots[i] >= 0 {
				r.initVals[i] = g.initEnv.get(r.varSlots[i], g.envDepth)
			}
		}
	}
}

// NewGrammar returns an empty grammar with the default limit MaxDepth on nested recursive rule calls.
//
// NewGrammar is for generated parsers; not a stable API.
func NewGrammar(maxDepth int) *grammar {
	return &grammar{maxDepth: maxDepth, StructFields: map[string]*structFields{},
		TypeKinds: map[string]*noderep.Kind{}, NodeTypes: map[string]*nodeTypeKinds{}}
}

// structFields holds the zero descriptor of each field of a struct type (spec/language/types.md#zero-values): i, s and b for 0, "" and false; n for nil; l for the
// empty list; the descriptors of the elements in parentheses for a tuple; {Name} for the struct type
// Name; and - for a type that has no zero value.
type structFields struct {
	zeros map[string]string
}

// DeclareStruct declares the struct type name with the fields given as name and zero descriptor pairs,
// in declaration order.
//
// DeclareStruct is for generated parsers; not a stable API.
func (g *grammar) DeclareStruct(name string, fieldZeros ...string) {
	sf := &structFields{zeros: make(map[string]string, len(fieldZeros)/2)}
	for i := 0; i+1 < len(fieldZeros); i += 2 {
		sf.zeros[fieldZeros[i]] = fieldZeros[i+1]
	}
	g.StructFields[name] = sf
}

// SetRules makes rules, of which nseen have rule.Seen set, the rule table of g.
func (g *grammar) SetRules(rules []*Rule, nseen int) {
	g.rules, g.nseen = rules, nseen
	defer g.indexInitVals()
	numberLeaders(rules)
	for _, r := range rules {
		r.g = g
		r.kinds = noderep.NewRuleKinds(r.Name)
		if r.NodeType != "" {
			r.nodeKinds = NewNodeTypeKinds(r.NodeType)
		}
		if r.OpNodeType != "" {
			r.opKinds = NewNodeTypeKinds(r.OpNodeType)
		}
	}
}

// Share gives g, the grammar of a recognizer, the tables of base other than its rules.
func (g *grammar) Share(base *grammar) {
	rules, nseen := g.rules, g.nseen
	*g = *base
	g.rules, g.nseen = rules, nseen
	g.indexInitVals() // the rules are the recognizer's own
}

func (g *grammar) ruleByName(name string) *Rule {
	for _, r := range g.rules {
		if r.Name == name {
			return r
		}
	}
	return nil
}

// StartRule returns the start rule name, or the error of StartError if name is not a start rule.
func (g *grammar) StartRule(name string) (*Rule, error) {
	if name == "" {
		name = g.DefaultStart
	}
	for _, s := range g.Starts {
		if s == name {
			return g.ruleByName(name), nil
		}
	}
	return nil, g.StartError(name)
}

// StartError returns the error for name, which is not a start rule: it names the rule and tells
// whether the grammar defines it or hides it.
func (g *grammar) StartError(name string) error {
	switch {
	case name == "":
		return fmt.Errorf("no start rule is given")
	case name[0] == '_':
		return fmt.Errorf("rule %s is hidden: a rule whose name begins with an underscore is not an entry point", name)
	case g.ruleByName(name) == nil:
		return fmt.Errorf("rule %s is not defined", name)
	}
	return fmt.Errorf("rule %s is not a start rule; parsing can begin only at a rule marked @start", name)
}

// ParseOption configures an individual parsing invocation. Options apply in order.
type ParseOption func(*parseOptions)

type parseOptions struct {
	unit     core.PositionUnit
	maxDepth int
	context  context.Context
	limits   core.Limits
	control  *BudgetControl
	prepared bool
	// expectations selects the recording of expectations; ResolveOptions rejects it for a parser
	// generated without them (WithExpectations, grammar.Expectations).
	expectations bool
	// maxInput is the resolved Input limit of a stream, in units; zero sets no bound.
	maxInput int
	// controls is set when the parser was generated with limit controls, which alone can apply the
	// default budget.
	controls bool
	// observe selects the observation of the parse (trace.go).
	observe observeOptions
	// streaming is set by the stream entry points, which alone accept the
	// diagnostic options.
	streaming          bool
	diagnostic         func(*core.SyntaxError) error
	diagnosticLimit    int
	diagnosticLimitSet bool
}

// WithUnit selects the unit of input positions (CodePoints by default).
func WithUnit(unit core.PositionUnit) ParseOption { return func(o *parseOptions) { o.unit = unit } }

// WithExpectations makes the parse record what a syntax error expects and the messages of @error,
// which the SyntaxError then lists. Without it the error carries the farthest failure position only.
// A parser generated without expectations has no WithExpectations, and a parse that passes the
// option through the library returns an error.
func WithExpectations() ParseOption { return func(o *parseOptions) { o.expectations = true } }

// WithContext selects cooperative cancellation for one invocation.
// A nil context is equivalent to context.Background.
func WithContext(ctx context.Context) ParseOption { return func(o *parseOptions) { o.context = ctx } }

// WithLimits sets the limits of the invocation field by field: a nonzero field overrides the value
// of an earlier WithLimits, including the construction defaults of a Document, and a zero field
// leaves it unchanged. A field that no option sets takes its default; Unlimited disables a limit.
// Counters are never rolled back.
func WithLimits(limits core.Limits) ParseOption {
	return func(o *parseOptions) { o.limits = mergeLimits(o.limits, limits) }
}

// ResolveOptions applies opts to the defaults of grammar g.
//
// ResolveOptions is for generated parsers; not a stable API.
func ResolveOptions(g *grammar, opts []ParseOption) (parseOptions, error) {
	if len(opts) == 0 {
		return parseOptions{maxDepth: g.maxDepth, controls: !g.NoBudgetControls}, nil
	}
	o := parseOptions{controls: !g.NoBudgetControls}
	for _, opt := range opts {
		opt(&o)
	}
	depth, err := resolveDepth(o.limits.Depth, g.maxDepth)
	if err != nil {
		return o, err
	}
	o.maxDepth = depth
	if g.NoBudgetControls && (o.context != nil || !limitsDisabled(o.limits)) {
		return o, fmt.Errorf("this parser was generated without limit controls (generate with -limits to use WithContext and a finite Compute or Memory limit)")
	}
	if o.expectations && !g.Expectations {
		return o, fmt.Errorf("this parser was generated without expectations (generate with -expectations to use WithExpectations)")
	}
	if err := o.validateDiagnostics(); err != nil {
		return o, err
	}
	if err := o.validateObservation(g); err != nil {
		return o, err
	}
	return o, nil
}

// resolveDepth returns the nesting limit that a Depth limit selects: the generated default def for
// zero. A generated parser nests rule calls on the goroutine stack, so Unlimited is an error.
func resolveDepth(depth uint64, def int) (int, error) {
	switch {
	case depth == 0:
		return def, nil
	case depth == core.Unlimited:
		return 0, fmt.Errorf("a generated parser does not accept an unlimited depth: it nests rule calls on the goroutine stack")
	case depth > math.MaxInt:
		return math.MaxInt, nil
	}
	return int(depth), nil
}

// validateObservation accepts the trace and profile options only for a parser generated with
// observability, which is the one that calls the observation.
func (o *parseOptions) validateObservation(g *grammar) error {
	ob := &o.observe
	if !g.Observable && (ob.trace != nil || ob.profile != nil || ob.rules != nil || ob.maxDepth != 0) {
		return fmt.Errorf("trace and profile options are only supported by a parser generated with observability")
	}
	return nil
}

// validateDiagnostics accepts the diagnostic options only for stream entry points.
func (o *parseOptions) validateDiagnostics() error {
	if o.diagnosticLimit < 0 {
		return fmt.Errorf("diagnostic limit must be nonnegative")
	}
	if !o.streaming && (o.diagnostic != nil || o.diagnosticLimitSet) {
		return fmt.Errorf("diagnostic options are only supported for stream parsing")
	}
	return nil
}

// prepareOptions is called after fixed option and rule-name validation. n is the length of the
// input in units of the position unit; a stream, whose length is not known, passes stream instead.
// A zero Compute selects the default budget of n (or the floor, growing with the input read, for a
// stream) in a parser generated with limit controls, and Unlimited disables the budget.
// The resolved state can be shared with a result converter without new counters.
func prepareOptions(o parseOptions, n uint64, stream bool) parseOptions {
	if !o.prepared {
		o.prepared = true
		l, adaptive := o.limits, false
		// A limit beyond math.MaxInt bounds no stream.
		if l.Input != 0 && l.Input != core.Unlimited && l.Input <= math.MaxInt {
			o.maxInput = int(l.Input)
		}
		l.Input = 0 // checked on entry, or by the stream; it needs no control
		if l.Memory == core.Unlimited {
			l.Memory = 0 // the default of Memory is Unlimited
		}
		switch {
		case l.Compute == core.Unlimited:
			l.Compute = 0
		case l.Compute == 0 && o.controls && stream:
			l.Compute, adaptive = defaultBudgetFloor, true
		case l.Compute == 0 && o.controls:
			l.Compute = defaultBudget(n)
		}
		if o.context != nil || l != (core.Limits{}) {
			o.control = newBudgetControl(o.context, l)
			if o.control != nil {
				o.control.adaptive = adaptive
			}
		}
	}
	o.control.Check()
	return o
}

// forDocument marks the control of o as that of a Document parse, whose default compute limit
// counts only the work that a parse from scratch counts (see BudgetControl.ChargeDoc). An explicit
// limit is unchanged.
func (o parseOptions) forDocument() parseOptions {
	if o.control != nil && o.limits.Compute == 0 && o.controls {
		o.control.defaultCompute = true
	}
	return o
}

// prepareText is prepareOptions for the input text of a batch parse or a Document. It rejects a text
// longer than the Input limit before any work: O(1), unless the byte length passes the limit in CodePoints,
// where the count of code points decides.
func prepareText(o parseOptions, text string) parseOptions {
	if !o.prepared {
		if max := o.limits.Input; max != 0 && max != core.Unlimited {
			n := uint64(len(text))
			if n > max && o.unit == core.CodePoints {
				n = uint64(utf8.RuneCountInString(text))
			}
			if n > max {
				panic(fatal{err: &core.LimitError{Kind: core.LimitInput, Limit: max, Requested: n}})
			}
		}
	}
	return prepareOptions(o, inputUnits(text, o.unit), false)
}

// recoverParse returns engine interruptions and preserves caller panic identity.
func recoverParse[T any](v *T, err *error) {
	if x := recover(); x != nil {
		switch x := x.(type) {
		case fatal:
			var zero T
			*v, *err = zero, x.err
		case tracePanic:
			panic(x.value)
		case contextPanic:
			panic(x.value)
		default:
			panic(x)
		}
	}
}

// RunParse parses the whole input with rule r.
//
// RunParse is for generated parsers; not a stable API.
func RunParse(r *Rule, input string, opts []ParseOption) (n *core.Node, err error) {
	o, err := ResolveOptions(r.g, opts)
	if err != nil {
		return nil, err
	}
	return RunParseResolved(r, input, o)
}

// RunParseResolved is for generated parsers; not a stable API.
func RunParseResolved(r *Rule, input string, o parseOptions) (n *core.Node, err error) {
	defer recoverParse(&n, &err)
	return parseResolvedSpend(r, input, o)
}

// parseResolvedSpend lets a conversion boundary distinguish engine interruption
// from an ordinary nil result without inspecting caller-owned error values.
func parseResolvedSpend(r *Rule, input string, o parseOptions) (n *core.Node, err error) {
	o = prepareText(o, input)
	p, _ := ppool.Get().(*Parser)
	if p == nil {
		p = &Parser{}
	}
	defer p.release()
	p.setGrammar(r.g)
	p.Expectations = o.expectations
	p.Control = o.control
	o.control.attachMemory(p)
	p.Observation = newObservation(&o.observe)
	p.MaxDepth = o.maxDepth
	if o.unit == core.Bytes {
		p.unit, p.bs, p.n = core.Bytes, input, len(input)
	} else {
		p.setSource(input)
	}
	p.memo.sparse = p.memo.stride > 64 && p.n > 1024
	p.Control.Check()
	v, ok := p.Call(r, 0)
	p.Control.Check()
	if ok && p.Pos == p.n {
		if len(p.Recovered) > 0 {
			return v, core.SyntaxErrors(p.recoveredErrors())
		}
		return v, nil
	}
	if ok {
		p.Expect(p.Pos, IdEndInput)
	}
	return nil, p.MakeError(p.farthest, p.exp[p.expBase:])
}

// ppool keeps parsers of parse, with their scratch memory, for later parses. What a parse returns
// never refers to that memory: nodes, child lists and fields come from slabs that are not kept,
// capture frames and slots are private scratch, and node text slices the input string.
var ppool sync.Pool

// release clears the parser and returns it to ppool, keeping decoded input, memo storage,
// capture scratch and construction stacks within their retention bounds.
func (p *Parser) release() {
	m := &p.memo
	discardMemo := cap(m.slots) > 1<<20 || len(m.chunks) > 1<<12 || cap(m.seen) > 1<<20
	clear(m.slots)
	for _, c := range m.chunks[:m.used] {
		clear(c)
	}
	m.resetSeen(1 << 20)
	clear(p.KidStack[:cap(p.KidStack)])
	clear(p.Trail[:cap(p.Trail)])
	clear(p.saved[:cap(p.saved)])
	frames := p.captureScratch
	if nodeFrameScratch && (frames.frames != nil || frames.slots != nil) {
		frames.reset()
	}
	in, offs := p.In[:0], p.offs[:0]
	if cap(in) > 1<<20 { // do not keep the buffers of a large input for every later parse
		in, offs = nil, nil
	}
	memo := memoTable{slots: m.slots[:0], chunks: m.chunks, seen: m.seen[:0], calls: m.calls, pages: m.pages, bitPages: m.bitPages}
	if discardMemo {
		memo = memoTable{}
	}
	*p = Parser{In: in, offs: offs, exp: p.exp[:0], arena: p.arena[:0], KidStack: p.KidStack[:0],
		Trail: p.Trail[:0], saved: p.saved[:0], memo: memo, captureScratch: frames}
	ppool.Put(p)
}

// --- Parser state ---

// ExpID is an expectation: an index into descs. With MsgBit set, it is an @error message.
//
// ExpID is for generated parsers; not a stable API.
type ExpID int32

// MsgBit is for generated parsers; not a stable API.
const MsgBit ExpID = 1 << 30

// ExpFar is the only entry of an expectation record in a parse that does not record expectations.
// It stands for a failure at the position of the record and describes nothing.
const ExpFar ExpID = 1 << 29

// Expectations at the start of every descs table. They are for generated parsers; not a
// stable API.
const (
	IdAny ExpID = iota
	IdBeginInput
	IdEndInput
	IdBeginLine
	IdEndLine
)

// Parser is for generated parsers; not a stable API.
type Parser struct {
	Control *BudgetControl
	g       *grammar // the grammar of the rules being parsed (setGrammar)
	// Observation observes the parse; it is nil unless the parse options select it.
	Observation *observation
	// SourceInfo is g.SourceInfo, read where values are made.
	sourceInfo bool
	// Document is set only by the private incremental runner.
	Document *documentState
	// docHigh is the exact end of the input that the active rule call of a Document parse examined:
	// one past the last unit that can influence its result, with the end of the input counting as
	// the unit at its length (docLow).
	docHigh int
	// The state of left recursion (context_memo.go): the growths in progress, innermost last; the
	// frames that record dependencies, and their dependencies; the dependencies of the call that
	// ctxPop ended; the context tables; the lookaheads in progress; the lookahead sites whose
	// outcome is being looked up; and the last seed identity given.
	gamma    []growRec
	frames   []depFrame
	deps     []dep
	popped   []dep
	ctxs     []*ctxTable
	looks    []lookRec
	obsGuard []int32
	seedSeq  uint64
	unit     core.PositionUnit
	In       []rune // code points (CodePoints)
	bs       string // the input (Bytes)
	n        int    // input length in units
	// src and offs give token text without copying in CodePoints mode: offs[i] is the byte offset
	// of code point i (len(in)+1 entries). For invalid UTF-8, offs is nil until the first text
	// replaces src by the decoded input (with U+FFFD substituted) and builds its table; decoded
	// records that this was tried. A valid source too large for int32 offsets (offsLimit) keeps
	// src with offs nil, and its first text builds the table wide of int offsets instead, so text
	// stays constant-cost at any size.
	src     string
	offs    []int32
	wide    []int
	decoded bool
	Pos     int

	MaxDepth int      // invocation-local maximum nesting
	Depth    int      // nesting of recursive rule calls
	created  []*core. // struct nodes made by the action being evaluated (from ActCtx.Cbase)
			Node
	Env      *Env
	envDepth int // the depth of Env (grammar.envDepth)
	Frame    *CaptureFrame
	Trail    []undo
	Cut      bool
	// cutFailed reports that a candidate of the last longest failed after a cut. It sits next to
	// Cut, in the padding after it.
	cutFailed bool
	// afterEmpty reports that the next expression is the right operand of an infix operator applied
	// without consuming input. It sits in the same padding.
	afterEmpty bool
	// nudBound is the binding level above which no operator can follow the start of the expression
	// that the last start parsed.
	nudBound int
	memo     memoTable

	// Silent is positive inside lookaheads, where expectations are not recorded.
	Silent   int
	farthest int
	// Expectations makes Expect record expectations (grammar.Expectations). Without it a record
	// holds at most the placeholder ExpFar, which stands for a failure at its position.
	Expectations bool
	// exp is the stack of expectations; the current record is exp[expBase:], all expected at
	// farthest.
	exp     []ExpID
	expBase int
	// expBits cheaply excludes IDs absent from the current record. Collisions still scan.
	expBits uint64
	// arena holds expectation sets kept by memo entries and recoveries (append-only chunks).
	arena    []ExpID
	lastKept []ExpID

	// Recovered is the record of the syntax errors recovered by #recover: errors and the lists that
	// results share (recEntry). Backtracking undoes them; recoveredErrors lists them.
	Recovered []recEntry

	// Result slabs, the stack that gathers repetition children, and the reused
	// evaluation context.
	nodeSlab  []core.Node
	ptrSlab   []*core.Node
	KidStack  []*core.Node
	frameSlab []CaptureFrame // per-parse reference allocation only
	// Capture slots are private scratch, separate from returned child lists.
	captureScratch frameScratch
	fieldSlab      []noderep.NodeField
	lines          []int // positions where lines start (MakeError)
	ac             ActCtx
	saved          []*core. // captures saved across a reset in longest
			Node
	// skipTables are the records of the walks of skip-run sites, indexed by 2*site, plus 1 in a
	// lookahead; skip is the walk in progress (skip_runs.go).
	skipTables []*skipSlots
	skip       skipWalk
	// scanTables are the records of the walks of scan sites by site, scanCold whether each site is hot,
	// by 2*site, plus 1 in a lookahead, and scanWalk the walk that ScanReach reached (scan_sites.go).
	scanTables []map[int]scanRecord
	scanCold   []scanCold
	scanWalk   scanWalk
	// Stream is set only by ParseStream: positions then index its buffer.
	Stream *streamInput
	// memUsed counts the bytes of the chunks the allocators have taken (budget_memory.go); a
	// stream's commit returns them. memKept counts those that stay in use for the whole parse.
	memUsed, memKept uint64
	// docLow is the start of the input that the active rule call examined, [docLow, docHigh). The
	// fields that only Documents use come last, away from those of every parse.
	docLow int
	// moved maps the nodes of a value that holds a node more than once to their copies
	// (documentMove).
	moved map[*core.Node]*core.Node
	// interned and internSeq number keys too large for a word while a growth is in progress (intern).
	// They come last, away from the fields of every parse.
	interned  map[string]uint64
	internSeq uint64
}

// documentState owns reusable memo entries. The regular Parse path never sets
// parser.Document.
type documentState struct {
	root *Rule
	text string
	unit core.PositionUnit
	// expectations is the recording mode of the Document, fixed at its construction.
	expectations bool
	memo         memoTable
	stats        documentStats
	// moves numbers the moves of values after edits (documentMove) over the life of the memo, not of
	// a parse: the nodes that the memo keeps carry the number of the last move that visited them from
	// one parse to the next, so a number is not used twice while the memo holds entries (parse).
	moves uint32
	// pending is the number of edits since the memo was last used by a parse (pendingEditLimit).
	pending int
	// epoch counts the edits of the Document (memoEntry.seen): an entry is current in a parse if it
	// carries the epoch of that parse, which no edit changes, and an entry that more than
	// pendingEditLimit edits have passed since it was last stored or found to answer a lookup is
	// dropped by the edit that makes it so (memoTable.splice).
	epoch uint32
}

type documentStats struct {
	Evaluated int
	Reused    int
}

// setGrammar prepares p to parse with the rules of g.
func (p *Parser) setGrammar(g *grammar) {
	p.g, p.sourceInfo, p.memo.stride = g, g.SourceInfo, g.nseen
	p.Env, p.envDepth = g.initEnv, g.envDepth
	if len(p.memo.calls) != g.nseen {
		p.memo.calls = nil // kept from a parse with another rule table
	}
}

// documentTouch records that the active rule call of a Document parse examined the input before
// end. Every caller passes the exact end of what it read: one past the last unit that its outcome
// depends on, so that an edit at or after that end leaves the outcome as it was.
func (p *Parser) documentTouch(end int) {
	if p.Document != nil && end > p.docHigh {
		p.docHigh = end
	}
}

// documentTouchLiteral records what a comparison of the literal text with the input at the position
// examined when it failed: the input up to its first unit that differs, or the end of the input.
func (p *Parser) documentTouchLiteral(text string) {
	k := 0
	for k < len(text) && p.Pos+k < p.n && p.bs[p.Pos+k] == text[k] {
		k++
	}
	p.documentTouch(p.Pos + k + 1)
}

// decodedEnd returns the end of the input that decoding the character at the start of s, at
// position pos, examined, for a character of size units: its units for a valid one, and for an
// invalid one the units up to the first that makes it invalid, or the end of the input (counted as
// the unit at its position) when the input ends inside a valid prefix.
func decodedEnd(s string, pos, size int) int {
	if size > 1 {
		return pos + size
	}
	k := 1
	for k <= len(s) && !utf8.FullRuneInString(s[:k]) {
		k++
	}
	return pos + k
}

// documentTouchFrom extends the input that the active rule call examined back to from.
func (p *Parser) documentTouchFrom(from int) {
	if p.Document != nil && from < p.docLow {
		p.docLow = from
	}
}

// documentTouchLine records that a line start test at the position examined the unit before it.
func (p *Parser) documentTouchLine() {
	if p.Document != nil {
		p.docHigh = max(p.docHigh, p.Pos)
		p.docLow = min(p.docLow, p.Pos-1)
	}
}

// memoTable maps (rule, position, level) to results. Each position has a chain of entries;
// entries are allocated in slabs.
type memoTable struct {
	slots []*memoEntry
	slab  []memoEntry
	// chunks are the areas slab came from, kept for later parses (release); used counts those in use.
	chunks [][]memoEntry
	used   int
	// seen is a bit set of the (position, rule) pairs called once (FirstCall), with stride bits per
	// position.
	seen   []uint64
	stride int
	sparse bool // selected once from rule count and input length
	// Large rule tables allocate only visited per-rule 1,024-position regions.
	pages    []seenRulePages
	bitPages seenPageArena
	// calls counts, per rule number, the calls and the repeated calls at a position; once repeats
	// are frequent, the rule is memoized on the first call (eager).
	calls []seenCalls
	// free links entries retired by stream memo pruning through next.
	free *memoEntry
	// shifts holds, for each entry that an edit of a Document moved (splice), how far the positions in
	// its value must move (documentMove).
	shifts map[*memoEntry]int
	// epoch is the edit count of the Document that owns the table (documentState.epoch) as of the edit
	// being spliced in; splice drops the entries that more than pendingEditLimit edits behind it.
	epoch uint32
	// index holds the hash index of each position whose chain is longer than a lookup walks
	// (memoScan), by position.
	index map[int]memoIndex[memoEntry]
	// indexBytes counts the bytes of index, for the memory limit (chargedBytes).
	indexBytes uint64
	// memBytes counts the bytes of the slots and first-call tables the table has taken into use
	// (chargedBytes).
	memBytes uint64
}

// seenRulePages caches the last visited page beside its directory. Most calls
// of a rule stay within one region, avoiding a second dependent pointer lookup.
type seenRulePages struct {
	pages []*[16]uint64
	last  *[16]uint64
	at    int
}

type seenCalls struct {
	calls, repeats int32
	eager          bool
}

// FirstCall records a call of rule r at the current position and reports whether its
// memoization is deferred: it is the first call there, and repeated calls of the rule have been
// rare so far. Results are reused only when a rule is called again at a position, which is rare,
// so memoizing every first call cost an entry each for nothing; deferring memoization to the
// second call evaluates a rule at most twice per position, which keeps parse time linear.
func (p *Parser) FirstCall(r *Rule) bool {
	// Documents memoize on the first call and never get here (callDocument).
	if p.Stream != nil {
		return false // streams memoize on the first call, as the engine does
	}
	if p.Control != nil {
		p.controlledFirstCallPrepare(r)
	}
	if r.Seen < 0 {
		return false
	}
	t := &p.memo
	if t.calls == nil {
		t.calls = make([]seenCalls, t.stride)
	}
	c := &t.calls[r.Seen]
	if c.eager {
		return false
	}
	// Discount old observations before the compact counters can wrap. Eager
	// mode is sticky; this estimator only chooses when to enter it.
	calls := uint32(c.calls) + 1
	if calls&(1<<31) != 0 {
		calls >>= 1
		c.repeats >>= 1
	}
	c.calls = int32(calls)
	var first bool
	if t.sparse {
		pos := p.Pos
		page := t.cachedSeenPage(pos, r.Seen)
		if page == nil {
			page = t.sparsePage(pos, r.Seen)
		}
		first = markSeenPage(page, pos)
	} else {
		first = t.markSeen(p.Pos, r.Seen)
	}
	if first {
		return true
	}
	// Deferring costs an extra evaluation for each position where the rule is called again, and
	// saves a memo entry for each position where it is not.
	c.repeats++
	if c.repeats > c.calls>>4 {
		c.eager = true
	}
	return false
}

// seenPageArena batches stable bit pages without one allocation per page.
type seenPageArena struct {
	chunks []*[64][16]uint64
	n      int
}

func (a *seenPageArena) alloc() *[16]uint64 {
	c := a.n / 64
	if c == len(a.chunks) {
		a.chunks = append(a.chunks, new([64][16]uint64))
	}
	page := &a.chunks[c][a.n%64]
	a.n++
	return page
}

func (a *seenPageArena) reset() {
	for i := 0; i < a.n; i++ {
		a.chunks[i/64][i%64] = [16]uint64{}
	}
	a.n = 0
}

// resetSeen clears first-call state and bounds sparse scratch storage by limit
// words, including unused directories and complete arena chunks.
func (t *memoTable) resetSeen(limit int) {
	clear(t.seen)
	clear(t.calls)
	if cap(t.seen) > 1<<20 {
		t.seen = nil
	}
	if cap(t.pages) > limit/5 || len(t.bitPages.chunks) > limit/(64*16) || cap(t.bitPages.chunks) > limit {
		t.pages, t.bitPages = nil, seenPageArena{}
		return
	}
	words := 5*cap(t.pages) + len(t.bitPages.chunks)*64*16 + cap(t.bitPages.chunks)
	if words <= limit {
		for _, dir := range t.pages {
			if cap(dir.pages) > limit-words {
				words = limit + 1
				break
			}
			words += cap(dir.pages)
		}
	}
	if words > limit {
		t.pages, t.bitPages = nil, seenPageArena{}
		return
	}
	for i := range t.pages {
		dir := &t.pages[i]
		clear(dir.pages)
		dir.pages = dir.pages[:0] // the length of a directory is the parse's own
		dir.last, dir.at = nil, 0
	}
	t.bitPages.reset()
}

func (t *memoTable) markSeen(pos, r int) bool {
	i := pos*t.stride + r
	w, b := i>>6, uint64(1)<<(i&63)
	if w >= len(t.seen) {
		t.seen = append(t.seen, make([]uint64, max(w+1-len(t.seen), len(t.seen), 64))...)
	}
	if t.seen[w]&b != 0 {
		return false
	}
	t.seen[w] |= b
	return true
}

// markSparseSeen records only visited per-rule regions, with page allocation
// batched to keep the directory savings from adding one allocation per page.
func (t *memoTable) markSparseSeen(pos, r int) bool {
	page := t.cachedSeenPage(pos, r)
	if page == nil {
		page = t.sparsePage(pos, r)
	}
	return markSeenPage(page, pos)
}

// cachedSeenPage and markSeenPage inline into FirstCall. Keeping allocation
// separate avoids another function call when a rule remains in its last page.
func (t *memoTable) cachedSeenPage(pos, r int) *[16]uint64 {
	if r < len(t.pages) {
		dir := &t.pages[r]
		if dir.at == pos>>10 {
			return dir.last
		}
	}
	return nil
}

func markSeenPage(page *[16]uint64, pos int) bool {
	w, b := (pos>>6)&15, uint64(1)<<(pos&63)
	first := page[w]&b == 0
	page[w] |= b
	return first
}

// sparsePage handles directory growth and page allocation off the hot path.
func (t *memoTable) sparsePage(pos, r int) *[16]uint64 {
	if len(t.pages) != t.stride {
		t.pages = make([]seenRulePages, t.stride)
	}
	dir := &t.pages[r]
	at := pos >> 10
	page := dir.last
	if page == nil || dir.at != at {
		pages := dir.pages
		if at >= len(pages) {
			if at < cap(pages) {
				pages = pages[:at+1]
			} else {
				grown := make([]*[16]uint64, at+1, max(at+1, 2*cap(pages), 4))
				copy(grown, pages)
				pages = grown
			}
			dir.pages = pages
		}
		page = pages[at]
		if page == nil {
			page = t.bitPages.alloc()
			pages[at] = page
		}
		dir.last, dir.at = page, at
	}
	return page
}

type memoEntry struct {
	node     *core.Node
	errs     recEntry   // errors recovered in this call, recorded again on reuse
	expected []ExpID    // expectations at far, recorded again on reuse
	next     *memoEntry // next entry at the same position
	env      []any      // values of the rule's variables at the call (memo key)
	end      int
	examined int // exclusive upper bound examined by a Document call
	far      int
	rule     int32
	min      int32
	ok       bool
	// silent means the result was computed inside a lookahead without recording expectations;
	// outside lookaheads it is computed again.
	silent bool
	// from and examined are the input that a Document call examined (memo.examine): from the
	// entry's position, or from the unit before it, to examined; from is noRecord for an entry
	// without a record. pinned keeps the entry from moving with an edit (memo.pin).
	from   examinedFrom
	pinned bool
	// present is the set of leaders (Rule.leaderBit) that grew at the position when a result of a
	// rule of their cycle was evaluated; it is reused only where every leader that grows there is in
	// the set (ctxCallState.memoAllows).
	present uint32
	// seen is the epoch of the Document (documentState.epoch) when a parse last stored the entry or
	// found it to answer a lookup; a parse from scratch leaves it zero.
	seen uint32
	// _ pads the entry to 128 bytes, two cache lines of the slab that holds it: at 120 bytes,
	// entries straddle lines and node parses ran about 2% slower.
	_ [4]byte
}

// get returns the entry for the rule, position, level and variable values.
func (t *memoTable) get(rule, pos, min int, env []any) *memoEntry {
	if pos >= len(t.slots) {
		return nil
	}
	e, n := t.slots[pos], 0
	for ; e != nil && n < memoScan; e, n = e.next, n+1 {
		if e.rule == int32(rule) && e.min == int32(min) && sameValues(e.env, env) {
			return e
		}
	}
	if e == nil {
		return nil
	}
	h, _ := memoKeyHash(int32(rule), int32(min), env)
	_, x := t.indexAt(pos).probe(h, func(x *memoEntry) bool {
		return x.rule == int32(rule) && x.min == int32(min) && sameValues(x.env, env)
	})
	return x
}

// indexAt returns the hash index of the chain at pos, building it on first use.
func (t *memoTable) indexAt(pos int) memoIndex[memoEntry] {
	return indexAt(&t.index, &t.indexBytes, pos, t.slots[pos], func(e *memoEntry) *memoEntry { return e.next },
		func(e *memoEntry) uint64 { h, _ := memoKeyHash(e.rule, e.min, e.env); return h })
}

// reindex makes the index of pos, if it has one, hold e where it held x, which has the key of e
// and is replaced by it in the chain.
func (t *memoTable) reindex(pos int, x, e *memoEntry) {
	if ix := t.index[pos]; ix != nil {
		h, _ := memoKeyHash(x.rule, x.min, x.env)
		slot, _ := ix.probe(h, func(y *memoEntry) bool { return y == x })
		ix[slot] = e
	}
}

// put stores e under the key, replacing an entry with the same key.
func (t *memoTable) put(rule, pos, min int, env []any, e *memoEntry) {
	if pos >= len(t.slots) {
		t.memBytes += uint64(pos+1-len(t.slots)) * ptrBytes
		if pos < cap(t.slots) {
			t.slots = t.slots[:pos+1]
		} else {
			grown := make([]*memoEntry, pos+1, max(2*cap(t.slots), pos+1, 64))
			copy(grown, t.slots)
			t.slots = grown
		}
	}
	e.rule, e.min, e.env = int32(rule), int32(min), env
	same := func(x *memoEntry) bool { return x.rule == e.rule && x.min == e.min && sameValues(x.env, env) }
	link := &t.slots[pos]
	for n := 0; *link != nil && n < memoScan; link, n = &(*link).next, n+1 {
		if x := *link; same(x) {
			t.reindex(pos, x, e)
			e.next = x.next
			*link = e
			return
		}
	}
	if *link != nil {
		// A long chain: the index finds the entry to replace, and a walk finds its link.
		ix := t.indexAt(pos)
		h, _ := memoKeyHash(e.rule, e.min, env)
		slot, x := ix.probe(h, same)
		ix[slot] = e
		if x == nil {
			t.indexBytes += memoIndexEntryBytes
		}
		if x != nil {
			link = &t.slots[pos]
			for *link != x {
				link = &(*link).next
			}
			e.next = x.next
			*link = e
			return
		}
	}
	e.next = t.slots[pos]
	t.slots[pos] = e
}

// sameValues reports whether two lists of variable values are equal.
func sameValues(a, b []any) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// noVals are the values of variables where no variable is defined (all nil): the memo key of
// most calls of a rule that reads variables, shared instead of allocated for each call. Memo
// entries only compare their keys, so nothing writes to it.
var noVals [16]any

// envValues returns the current values of the variables in slots (nil for a slot below zero, an
// undeclared variable).
func (p *Parser) envValues(slots []int) []any {
	if p.Control != nil {
		return p.controlledEnvValues(slots)
	}

	if len(slots) == 0 {
		return nil
	}
	if p.Env == nil && len(slots) <= len(noVals) {
		return noVals[:len(slots):len(slots)]
	}
	vals := make([]any, len(slots))
	for i, slot := range slots {
		if slot >= 0 {
			vals[i] = p.Env.get(slot, p.envDepth)
		}
	}
	return vals
}

// memoEnv returns the values of the variables the memoized rule r reads, for its memo key. While
// nothing has been bound since the parse began they are the initial values, computed once: the
// key only compares them, so the slice is shared instead of allocated for each call.
func (p *Parser) memoEnv(r *Rule) []any {
	if p.Env != nil && p.Env == p.g.initEnv && r.initVals != nil && p.Control == nil {
		return r.initVals
	}
	p.chargeValueBytes(len(r.varSlots) * int(anyBytes))
	return p.envValues(r.varSlots)
}

func (t *memoTable) alloc() *memoEntry {
	if e := t.free; e != nil {
		t.free, e.next = e.next, nil
		return e
	}
	if len(t.slab) == 0 {
		if t.used < len(t.chunks) {
			t.slab = t.chunks[t.used]
		} else {
			t.slab = make([]memoEntry, 256)
			t.chunks = append(t.chunks, t.slab)
		}
		t.used++
	}
	e := &t.slab[0]
	t.slab = t.slab[1:]
	return e
}

// CaptureFrame is for generated parsers; not a stable API.
type CaptureFrame struct{ Vals []*core.Node }

// EmptyFrame is for generated parsers; not a stable API.
var EmptyFrame = &CaptureFrame{}

const (
	nodeChunk = 256
	ptrChunk  = 1024
)

// NewNode returns a copy of v allocated from the node slab. A slab stays alive while any of its
// nodes is referenced.
func (p *Parser) NewNode(v Data) *core.Node {
	p.Spend()
	if len(p.nodeSlab) == 0 {
		p.nodeSlab = make([]core.Node, nodeChunk)
		p.memUsed += nodeChunk * nodeBytes
		if p.Stream != nil {
			p.Stream.nodeChunks++
		}
	}
	n := &p.nodeSlab[0]
	p.nodeSlab = p.nodeSlab[1:]
	*D(n) = v
	return n
}

// NewNodeOrdinary is NewNode in an ordinary parse (ExpectOrdinary).
func (p *Parser) NewNodeOrdinary(v Data) *core.Node {
	if len(p.nodeSlab) == 0 {
		p.nodeSlab = make([]core.Node, nodeChunk)
		if p.Stream != nil {
			p.Stream.nodeChunks++
		}
	}
	n := &p.nodeSlab[0]
	p.nodeSlab = p.nodeSlab[1:]
	*D(n) = v
	return n
}

// NewTerminal returns the node of text matched from start to the current position, allocated like
// NewNode(Data{Kind: noderep.MatchKind, ...}).
func (p *Parser) NewTerminal(start int, text string) *core.Node {
	p.Spend()
	return p.NewTerminalOrdinary(start, text)
}

// NewTerminalOrdinary is NewTerminal in an ordinary parse (ExpectOrdinary).
func (p *Parser) NewTerminalOrdinary(start int, text string) *core.Node {
	if len(p.nodeSlab) == 0 {
		p.nodeSlab = make([]core.Node, nodeChunk)
		p.memUsed += nodeChunk * nodeBytes
		if p.Stream != nil {
			p.Stream.nodeChunks++
		}
	}
	n := &p.nodeSlab[0]
	p.nodeSlab = p.nodeSlab[1:]
	*D(n) = Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: text, Terminal: true, Fresh: true}
	return n
}

// NewBranch returns the node of kind (noderep.SeqKind or noderep.ListKind) with children from start to the
// current position, allocated like NewNode(Data{Kind: kind, ...}).
func (p *Parser) NewBranch(kind *noderep.Kind, start int, children []*core.Node) *core.Node {
	p.Spend()
	return p.NewBranchOrdinary(kind, start, children)
}

// NewBranchOrdinary is NewBranch in an ordinary parse (ExpectOrdinary).
func (p *Parser) NewBranchOrdinary(kind *noderep.Kind, start int, children []*core.Node) *core.Node {
	if len(p.nodeSlab) == 0 {
		p.nodeSlab = make([]core.Node, nodeChunk)
		p.memUsed += nodeChunk * nodeBytes
		if p.Stream != nil {
			p.Stream.nodeChunks++
		}
	}
	n := &p.nodeSlab[0]
	p.nodeSlab = p.nodeSlab[1:]
	*D(n) = Data{Kind: kind, Start: int32(start), End: int32(p.Pos), Children: children, Fresh: true}
	return n
}

// Nodes returns a child list of length and capacity n from the pointer slab.
func (p *Parser) Nodes(n int) []*core.Node {
	if n == 0 {
		return []*core.Node{}
	}
	if n > ptrChunk/4 {
		p.memUsed += uint64(n) * ptrBytes
		return make([]*core.Node, n)
	}
	if len(p.ptrSlab) < n {
		p.ptrSlab = make([]*core.Node, ptrChunk)
		p.memUsed += ptrChunk * ptrBytes
	}
	s := p.ptrSlab[:n:n]
	p.ptrSlab = p.ptrSlab[n:]
	return s
}

// fields returns an empty field list with capacity n from a chunk. Appending beyond n
// reallocates, so neighbouring lists in the chunk are never overwritten.
func (p *Parser) fields(n int) noderep.Fields {
	if n > nodeChunk/4 {
		p.memUsed += uint64(n) * fieldBytes
		return make(noderep.Fields, 0, n)
	}
	if len(p.fieldSlab) < n {
		p.fieldSlab = make([]noderep.NodeField, nodeChunk)
		p.memUsed += nodeChunk * fieldBytes
	}
	fs := p.fieldSlab[:0:n]
	p.fieldSlab = p.fieldSlab[n:]
	return fs
}

// Kids returns p.KidStack[base:] as a child list and pops it.
func (p *Parser) Kids(base int) []*core.Node {
	ks := p.Nodes(len(p.KidStack) - base)
	copySpend(p, ks, p.KidStack[base:])
	p.DropKids(base)
	return ks
}

// DropKids pops p.KidStack[base:].
func (p *Parser) DropKids(base int) {
	clear(p.KidStack[base:])
	p.KidStack = p.KidStack[:base]
}

// NewFrame returns a capture frame with n slots.
func (p *Parser) NewFrame(n int) *CaptureFrame {
	if n == 0 {
		return EmptyFrame // never written, so shared
	}
	if nodeFrameScratch {
		return p.captureScratch.alloc(n)
	}
	if len(p.frameSlab) == 0 {
		p.frameSlab = make([]CaptureFrame, nodeChunk)
		p.memUsed += nodeChunk * frameBytes
	}
	f := &p.frameSlab[0]
	p.frameSlab = p.frameSlab[1:]
	f.Vals = p.Nodes(n)
	return f
}

// nodeFrameScratch selects capture frames from parser scratch; the per-parse
// frame slab remains only as the disabled alternative.
const nodeFrameScratch = true

// frameScratch keeps stable capture frames and slots until the parse returns.
// Neither array can be reached through a returned Node's children or fields.
// Append-only allocation also preserves retained OperatorsRule attempts and undo marks.
type frameScratch struct {
	frames  []*[nodeChunk]CaptureFrame
	slots   []*[ptrChunk]*core.Node
	frameN  int
	slotCI  int
	slotOff int
	// large counts the bytes of the frames allocated on their own (bytes).
	large uint64
}

const frameScratchLimit = 1 << 20 // native words of complete reusable backing

func (a *frameScratch) alloc(n int) *CaptureFrame {
	if n > ptrChunk/4 {
		// Large individual scopes are exact allocations, never pooled.
		a.large += frameBytes + uint64(n)*ptrBytes
		return &CaptureFrame{Vals: make([]*core.Node, n)}
	}
	ci := a.frameN / nodeChunk
	if ci == len(a.frames) {
		a.frames = append(a.frames, new([nodeChunk]CaptureFrame))
	}
	f := &a.frames[ci][a.frameN%nodeChunk]
	a.frameN++
	if a.slotOff+n > ptrChunk {
		a.slotCI++
		a.slotOff = 0
	}
	if a.slotCI == len(a.slots) {
		a.slots = append(a.slots, new([ptrChunk]*core.Node))
	}
	f.Vals = a.slots[a.slotCI][a.slotOff : a.slotOff+n : a.slotOff+n]
	a.slotOff += n
	return f
}

// reset clears the complete pointer-bearing backing before reuse or discard.
// Count three native words per frame slice header and nine for the arena state,
// plus whole chunks and directory capacity, including their unused elements.
func (a *frameScratch) reset() {
	for _, chunk := range a.frames {
		clear(chunk[:])
	}
	for _, chunk := range a.slots {
		clear(chunk[:])
	}
	clear(a.frames[len(a.frames):cap(a.frames)])
	clear(a.slots[len(a.slots):cap(a.slots)])
	if len(a.frames) > frameScratchLimit/(3*nodeChunk) || len(a.slots) > frameScratchLimit/ptrChunk ||
		cap(a.frames) > frameScratchLimit || cap(a.slots) > frameScratchLimit {
		*a = frameScratch{}
		return
	}
	words := 9 + 3*nodeChunk*len(a.frames) + ptrChunk*len(a.slots) + cap(a.frames) + cap(a.slots)
	if words > frameScratchLimit {
		*a = frameScratch{}
		return
	}
	a.frameN, a.slotCI, a.slotOff, a.large = 0, 0, 0, 0
}

type undo struct {
	f    *CaptureFrame
	slot int
	old  *core.Node
}

// Env is for generated parsers; not a stable API. It is a persistent vector with one current
// value per declared variable, indexed by the variable's slot (its position in declaration
// order). A vector of at most envWidth variables is one node holding the values; a larger one
// is a trie of nodes with envWidth children, whose depth (the levels above the leaves) every
// holder knows from the variable count. Environments saved for rollback are never modified: a
// rebind copies the nodes on the path to its slot and shares the rest.
type Env struct {
	// vals holds the values of a leaf; in an inner node every element is the *Env of a child.
	vals []any
}

const (
	envBits  = 4
	envWidth = 1 << envBits
	envMask  = envWidth - 1
)

// envDepthOf returns the number of levels above the leaves of an environment of n variables.
func envDepthOf(n int) int {
	levels := 0
	for limit := envWidth; n > limit; limit <<= envBits {
		levels++
	}
	return levels
}

// newEnv returns the environment that holds vals; levels is envDepthOf(len(vals)).
func newEnv(vals []any, levels int) *Env {
	if len(vals) == 0 {
		return nil
	}
	if levels == 0 {
		return &Env{vals: append([]any(nil), vals...)}
	}
	span := 1 << (envBits * levels)
	kids := make([]any, 0, (len(vals)+span-1)/span)
	for lo := 0; lo < len(vals); lo += span {
		hi := min(lo+span, len(vals))
		kids = append(kids, newEnv(vals[lo:hi], levels-1))
	}
	return &Env{vals: kids}
}

// get returns the value of the variable in slot i.
func (e *Env) get(i, levels int) any {
	for l := levels; l > 0; l-- {
		e = e.vals[i>>(envBits*l)&envMask].(*Env)
	}
	return e.vals[i&envMask]
}

// set returns the environment that differs from e in the value of slot i. The copied nodes are
// those on the path to the slot: levels+1 of them.
func (e *Env) set(i, levels int, v any) *Env {
	if levels == 0 {
		return e.setLeaf(i, v)
	}
	k := i >> (envBits * levels) & envMask
	kids := make([]any, len(e.vals))
	copy(kids, e.vals)
	kids[k] = e.vals[k].(*Env).set(i&(1<<(envBits*levels)-1), levels-1, v)
	return &Env{vals: kids}
}

// setLeaf copies a leaf. The leaves of up to four variables, the common case, are allocated
// together with their values.
func (e *Env) setLeaf(i int, v any) *Env {
	switch len(e.vals) {
	case 1:
		n := &struct {
			Env
			a [1]any
		}{a: [1]any{v}}
		n.vals = n.a[:]
		return &n.Env
	case 2:
		n := &struct {
			Env
			a [2]any
		}{a: [2]any(e.vals)}
		n.a[i] = v
		n.vals = n.a[:]
		return &n.Env
	case 3:
		n := &struct {
			Env
			a [3]any
		}{a: [3]any(e.vals)}
		n.a[i] = v
		n.vals = n.a[:]
		return &n.Env
	case 4:
		n := &struct {
			Env
			a [4]any
		}{a: [4]any(e.vals)}
		n.a[i] = v
		n.vals = n.a[:]
		return &n.Env
	}
	vals := make([]any, len(e.vals))
	copy(vals, e.vals)
	vals[i] = v
	return &Env{vals: vals}
}

// bind rebinds the variable in slot i, copying the path to the slot and preserving saved
// environments. Binding the value it has already is a no-op.
func (p *Parser) bind(slot int, val any) {
	if p.Control != nil {
		p.bindControlled(slot, val)
		return
	}
	// Variables are checked scalar values; an equal binding has no effect.
	if p.Env.get(slot, p.envDepth) == val {
		return
	}
	p.Env = p.Env.set(slot, p.envDepth, val)
}

// variable returns the value of the variable in slot i.
func (p *Parser) variable(slot int) any {
	if p.Control != nil {
		for l := 0; l <= p.envDepth; l++ {
			p.Spend()
		}
	}
	return p.Env.get(slot, p.envDepth)
}

// Mark is for generated parsers; not a stable API.
type Mark struct {
	Pos, Trail, recovered int
	env                   *Env
}

func (p *Parser) Mark() Mark {
	return Mark{Pos: p.Pos, env: p.Env, Trail: len(p.Trail), recovered: len(p.Recovered)}
}

func (p *Parser) SetCapture(slot int, v *core.Node) {
	p.Trail = append(p.Trail, undo{f: p.Frame, slot: slot, old: p.Frame.Vals[slot]})
	p.Frame.Vals[slot] = v
}

// offsLimit is the largest source whose offset table holds int32 offsets; a variable so that
// tests can exercise the wide table without gigabytes of input.
var offsLimit = 1<<31 - 1

// setSource decodes the input s into code points and, if s is valid UTF-8, records the offset
// table for token text, all in one pass (a U+FFFD that decodes from three bytes is valid).
func (p *Parser) setSource(s string) {
	if p.Control != nil {
		p.setControlledSource(s)
		return
	}
	n := utf8.RuneCountInString(s)
	// The buffers of a parser used before are reused (the typed library keeps parsers).
	if cap(p.In) >= n {
		p.In = p.In[:n]
	} else {
		p.In = make([]rune, n)
	}
	p.n = n
	tabled := len(s) <= offsLimit
	offs := p.offs[:0]
	if !tabled {
		offs = nil
	} else if cap(offs) >= n+1 {
		offs = offs[:n+1]
	} else {
		offs = make([]int32, n+1)
	}
	valid := true
	i := 0
	for off, r := range s {
		if r == utf8.RuneError && valid {
			if _, size := utf8.DecodeRuneInString(s[off:]); size == 1 {
				valid = false
			}
		}
		p.In[i] = r
		if tabled {
			offs[i] = int32(off)
		}
		i++
	}
	p.decoded, p.wide = false, nil
	if !valid {
		p.src, p.offs = "", nil
		return
	}
	p.src = s
	if tabled {
		offs[n] = int32(len(s))
		p.offs = offs
	} else {
		p.offs = nil
	}
}

// decodeSource replaces the source of a code-point input containing invalid UTF-8 by its decoded
// text and builds its offset table, so that text slices it like a valid source. It runs once, on
// the first text, and costs the length of the input; a recognition that takes no text never pays
// it.
func (p *Parser) decodeSource() {
	s := p.src
	if s == "" {
		if p.Control != nil {
			s = p.detachedText(0, p.n)
		} else {
			s = string(p.In[:p.n])
		}
	}
	wide := len(s) > offsLimit
	var offs []int32
	var woffs []int
	if wide {
		woffs = make([]int, 0, p.n+1)
	} else {
		offs = make([]int32, 0, p.n+1)
	}
	for off := 0; off < len(s); {
		if p.Control != nil {
			p.Control.Charge(uint64(min(spendValueChunk, len(s)-off)))
		}
		end := min(off+spendValueChunk, len(s))
		for off < end {
			_, size := utf8.DecodeRuneInString(s[off:])
			if wide {
				woffs = append(woffs, off)
			} else {
				offs = append(offs, int32(off))
			}
			off += size
		}
		// The last character may end past the chunk; charge the rest, so the table costs its bytes.
		if p.Control != nil && off > end {
			p.Control.Charge(uint64(off - end))
		}
	}
	// An interrupted decoding leaves the parser untouched, so the next text retries it.
	if wide {
		p.src, p.wide, p.decoded = s, append(woffs, len(s)), true
		return
	}
	p.src, p.offs, p.decoded = s, append(offs, int32(len(s))), true
}

// Peek returns the character at the current position and its size in units.
func (p *Parser) Peek() (rune, int, bool) {
	if p.Stream != nil {
		return p.streamPeek()
	}
	p.SpendRead(1)
	if p.Pos >= p.n {
		p.documentTouch(p.Pos + 1)
		return 0, 0, false
	}
	if p.unit == core.Bytes {
		if c := p.bs[p.Pos]; c < utf8.RuneSelf {
			p.documentTouch(p.Pos + 1)
			return rune(c), 1, true
		}
		p.SpendRead(uint64(min(utf8.UTFMax, p.n-p.Pos)))
		r, size := utf8.DecodeRuneInString(p.bs[p.Pos:])
		if p.Document != nil {
			p.documentTouch(decodedEnd(p.bs[p.Pos:], p.Pos, size))
		}
		return r, size, true
	}
	p.documentTouch(p.Pos + 1)
	return p.In[p.Pos], 1, true
}

// NextOrdinary is PeekOrdinary with the common case, a code-point input, written so that the
// compiler inlines it (the named results keep it within the inlining budget).
func (p *Parser) NextOrdinary() (r rune, size int, ok bool) {
	if p.Pos < len(p.In) {
		return p.In[p.Pos], 1, true
	}
	r, size, ok = p.PeekOrdinary()
	return
}

// PeekOrdinary is peek in an ordinary parse (ExpectOrdinary).
func (p *Parser) PeekOrdinary() (rune, int, bool) {
	if p.Stream != nil {
		return p.streamPeek()
	}
	if p.Pos >= p.n {
		return 0, 0, false
	}
	if p.unit == core.Bytes {
		if c := p.bs[p.Pos]; c < utf8.RuneSelf {
			return rune(c), 1, true
		}
		r, size := utf8.DecodeRuneInString(p.bs[p.Pos:])
		return r, size, true
	}
	return p.In[p.Pos], 1, true
}

func (p *Parser) unitLen(s string) int {
	if p.Control != nil && p.unit != core.Bytes {
		count := 0
		for off := 0; off < len(s); {
			p.spendValue(min(utf8.UTFMax, len(s)-off))
			_, size := utf8.DecodeRuneInString(s[off:])
			off += size
			count++
		}
		return count
	}

	if p.unit == core.Bytes {
		return len(s)
	}
	return utf8.RuneCountInString(s)
}

// ExpMark is the expectation record before isolate.
//
// ExpMark is for generated parsers; not a stable API.
type ExpMark struct {
	far, base int
	bits      uint64
}

// Isolate starts a separate expectation record whose farthest position is pos.
func (p *Parser) Isolate(pos int) ExpMark {
	m := ExpMark{p.farthest, p.expBase, p.expBits}
	p.expBase, p.farthest, p.expBits = len(p.exp), pos, 0
	return m
}

// Unisolate ends the separate record and returns its farthest position and expectations. The
// expectations alias the stack and are valid only until the next record (passing them to
// MergeExpected is fine; keep copies them).
func (p *Parser) Unisolate(m ExpMark) (far int, inner []ExpID) {
	far, inner = p.farthest, p.exp[p.expBase:]
	p.exp = p.exp[:p.expBase]
	p.expBase, p.farthest, p.expBits = m.base, m.far, m.bits
	return far, inner
}

func slicesEqual(a, b []ExpID) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (p *Parser) Text(start, end int) string {
	if p.Stream != nil {
		return p.streamText(start, end)
	}
	if p.unit == core.Bytes {
		return p.bs[start:end]
	}
	if p.offs == nil && !p.decoded {
		p.decodeSource()
	}
	if p.offs != nil {
		return p.src[p.offs[start]:p.offs[end]]
	}
	if p.wide != nil {
		return p.src[p.wide[start]:p.wide[end]]
	}
	if p.Control != nil {
		return p.detachedText(start, end)
	}
	return string(p.In[start:end])
}

type fatal struct{ err error }

func (p *Parser) MakeError(pos int, expected []ExpID) *core.SyntaxError {
	if p.Control != nil {
		return p.makeControlledError(pos, expected)
	}
	e := &core.SyntaxError{Pos: pos}
	for _, x := range expected {
		if x == ExpFar {
			continue
		}
		if x&MsgBit != 0 {
			e.Messages = append(e.Messages, p.g.Descs[x&^MsgBit])
		} else {
			e.Expected = append(e.Expected, p.g.Descs[x])
		}
	}
	sortExpectedEntries(e.Expected)
	if p.Stream != nil {
		e.Line, e.Col = p.streamLineCol(pos)
		return e
	}
	// Look the line up in a table of line starts, built on the first error, instead of scanning
	// from the start of the input for each error.
	if p.lines == nil {
		p.lines = append(p.lines, 0)
		for i := 0; i < p.n; i++ {
			if p.unit == core.Bytes && p.bs[i] == '\n' || p.unit == core.CodePoints && p.In[i] == '\n' {
				p.lines = append(p.lines, i+1)
			}
		}
	}
	pos = min(pos, p.n)
	i := sort.SearchInts(p.lines, pos+1)
	e.Line, e.Col = i, pos-p.lines[i-1]+1
	return e
}

// --- Rule calls ---

// ExaminedBegin starts measuring the examined end of an observed call in a
// Document parse, returning that of the enclosing call for ExaminedEnd. The call
// itself, and any memo entry it reads or records, extends the end as in an
// unobserved parse, so observation does not change reuse.
func (p *Parser) ExaminedBegin() int {
	h := p.docHigh
	if p.Document != nil {
		p.docHigh = p.Pos
	}
	return h
}

// ExaminedEnd returns the examined end of the call and merges it into the
// enclosing one. Outside a Document parse the end is unknown.
func (p *Parser) ExaminedEnd(enclosing int) (int, bool) {
	if p.Document == nil {
		return 0, false
	}
	x := p.docHigh
	p.docHigh = max(enclosing, x)
	return x, true
}

// releaseObservation ends the parse's observation.
func (p *Parser) releaseObservation() {
	p.Observation.release()
	p.Observation = nil
}

// invoke evaluates the body of r and makes the rule's value.
func (p *Parser) invoke(r *Rule, min int) (*core.Node, bool) {
	if p.Document != nil || p.Observation != nil {
		p.evaluating()
	}
	f := p.NewFrame(len(r.Scope))
	prevFrame, prevEnv, prevCut, trail := p.Frame, p.Env, p.Cut, len(p.Trail)
	p.Frame, p.Cut = f, false
	if r.Rec {
		p.Enter()
	}
	start := p.Pos
	v, ok := r.Body(p, min)
	if r.Rec {
		p.Depth--
	}
	p.Frame, p.Cut = prevFrame, prevCut
	p.Trail = p.Trail[:trail]
	if ok {
		v = p.Finish(r, f, v, start)
	}
	p.Env = prevEnv
	return v, ok
}

// InvokePlain is an unmemoized call of a rule without captures: invoke without the capture
// frame (the body never writes one, so the caller's stays current), with the failure handling of
// call.
func (p *Parser) InvokePlain(r *Rule, min int) (*core.Node, bool) {
	if p.Observation != nil {
		return p.invokePlainObserved(r, min)
	}
	return p.invokePlainBody(r, min)
}

// invokePlainBody is InvokePlain without observation.
func (p *Parser) invokePlainBody(r *Rule, min int) (*core.Node, bool) {
	if p.Document != nil || p.Observation != nil {
		p.evaluating()
	}
	start, rec, trail := p.Pos, len(p.Recovered), len(p.Trail)
	prevEnv, prevCut := p.Env, p.Cut
	p.Cut = false
	if r.Rec {
		p.Enter()
	}
	v, ok := r.Body(p, min)
	if r.Rec {
		p.Depth--
	}
	p.Cut = prevCut
	p.Trail = p.Trail[:trail]
	if ok {
		v = p.Finish(r, EmptyFrame, v, start)
	} else {
		p.Pos = start
		p.Recovered = p.Recovered[:rec]
	}
	p.Env = prevEnv
	return v, ok
}

// evaluating counts an evaluation of a rule body for the Document's statistics and the
// observation.
func (p *Parser) evaluating() {
	if p.Document != nil {
		p.Document.stats.Evaluated++
	}
	p.Observation.Evaluated()
}

// TooDeep fails the parse for exceeding the nesting limit.
func (p *Parser) TooDeep() {
	panic(fatal{err: &core.LimitError{Kind: core.LimitDepth, Limit: uint64(p.MaxDepth), Used: uint64(p.MaxDepth), Requested: 1}})
}

// Enter counts one more nested entry of a recursive rule and fails the parse beyond the nesting
// limit.
func (p *Parser) Enter() {
	p.Depth++
	if p.Depth > p.MaxDepth {
		p.TooDeep()
	}
}

// Restore goes back to the position pos and to the recovered errors of the first rec, as a failed
// alternative does.
func (p *Parser) Restore(pos, rec int) {
	p.Pos = pos
	p.Recovered = p.Recovered[:rec]
}

// Finish makes the rule's value from the value of its body.
func (p *Parser) Finish(r *Rule, f *CaptureFrame, v *core.Node, start int) *core.Node {
	v, owned := p.finishValue(r, f, v, start)
	if r.nodeKinds != nil {
		if owned && r.nodeKinds.convertOwned(v) {
			return v
		}
		v = p.convertResult(r, v)
	}
	return v
}

// convertResult converts v, the value of rule r, to the rule's named node type.
func (p *Parser) convertResult(r *Rule, v *core.Node) *core.Node {
	n, ok := r.nodeKinds.convert(UnboxNode(v))
	if !ok {
		panic(fatal{fmt.Errorf("cannot convert %s to %s in result of rule %s", typeName(UnboxNode(v)), r.NodeType, r.where())})
	}
	return n
}

func (p *Parser) finishValue(r *Rule, f *CaptureFrame, v *core.Node, start int) (*core.Node, bool) {
	if r.Novalue {
		return nil, false
	}
	if r.Action != nil {
		c := p.useCtx(ActCtx{P: p, f: f, start: start, end: p.Pos, cbase: len(p.created)})
		if r.OperatorsRule != nil {
			c.Value = UnboxNode(v)
		}
		return c.result(r.Action, r.where()), false
	}
	if r.Splice {
		if v != nil {
			D(v).Fresh = false
		}
		return v, false
	}
	v = p.ScopeValue(r.Value, v, start)
	if len(r.Scope) > 0 {
		v = p.AttachCaptures(v, r.Scope, f, start, p.Pos)
	}
	if v == nil {
		return nil, false
	}
	owned := D(v).Fresh
	if owned {
		if p.sourceInfo && D(v).Kind.Rule == "" {
			D(v).Kind = r.kinds.Named(D(v).Kind, r.Name)
		}
		D(v).Fresh = false
	}
	return v, owned
}

// AttachCaptures attaches the non-nil captures as fields of the node. A node of another rule, or
// one that is itself captured, is first wrapped in a tuple node.
func (p *Parser) AttachCaptures(v *core.Node, names []string, f *CaptureFrame, start, end int) *core.Node {
	found := false
	wrap := v == nil || !D(v).Fresh
	for _, c := range f.Vals {
		p.Spend()
		if c != nil {
			found = true
		}
		if c != nil && c == v {
			wrap = true
		}
	}
	if !found {
		return v
	}
	if wrap {
		v = p.NewNode(Data{Kind: noderep.SeqKind, Start: int32(start), End: int32(end), Children: append(p.Nodes(1)[:0], v), Fresh: true})
	}
	if D(v).Fields == nil {
		D(v).Fields = p.fields(len(names))
	}
	D(v).Labeled = p.sourceInfo
	for i, name := range names {
		p.Spend()
		if f.Vals[i] != nil {
			p.setValueField(&D(v).Fields, name, f.Vals[i])
		}
	}
	return v
}

func nodeOrNil(n *core.Node) any {
	if n == nil {
		return nil
	}
	return n
}

// --- Shapes of values ---

// singleMode is how an expression gives its value where it takes one element: an alternative,
// the operand of ?, a capture or a recovered expression.
type singleMode uint8

const (
	singleNone  singleMode = iota // no value
	singlePass                    // the one element
	singleTuple                   // the node of the tuple of the elements
)

// where returns the text that names the rule in the message of a failed action.
func (r *Rule) where() string {
	if r.Where != "" {
		return r.Where
	}
	return r.Name
}

// Shaper converts the result of an expression's method to the value where the expression takes
// one element or is a scope (a rule body, a repetition element or an Operators Rule line). The
// generator fills it from the expression's static shape, as the engine does.
//
// Shaper is for generated parsers; not a stable API.
type Shaper struct {
	Elems bool       // the method returns the tuple node of its elements
	K     int        // the number of valued elements
	Mode  singleMode // how the expression takes one element
	Tuple bool       // the value of a scope is the node of its tuple, rather than its one element
	// Shared means the tuple node the method returns (Elems) is the result of a splice rule, shared
	// through its memo entry: a node that takes it as its own takes a copy.
	Shared bool
}

// shapeTuple returns the tuple node of the result v of a match of [start, p.Pos).
func (p *Parser) shapeTuple(s Shaper, v *core.Node, start int) *core.Node {
	if s.Elems {
		if s.Shared && v != nil {
			return p.NewNode(Data{Kind: noderep.SeqKind, Start: D(v).Start, End: D(v).End, Children: D(v).Children, Fresh: true})
		}
		return v
	}
	var kids []*core.Node
	if s.K == 1 {
		kids = p.Nodes(1)
		kids[0] = v
	}
	return p.NewNode(Data{Kind: noderep.SeqKind, Start: int32(start), End: int32(p.Pos), Children: kids, Fresh: true})
}

// one returns the one element of the result v.
func (s Shaper) one(v *core.Node) *core.Node {
	if s.Elems {
		if v == nil || len(D(v).Children) == 0 {
			return nil
		}
		return D(v).Children[0]
	}
	return v
}

// ShapeSingle returns the value of the result v where the expression takes one element; ok is
// false when it has no value.
func (p *Parser) ShapeSingle(s Shaper, v *core.Node, start int) (*core.Node, bool) {
	switch s.Mode {
	case singlePass:
		return s.one(v), true
	case singleTuple:
		return p.shapeTuple(s, v, start), true
	}
	return nil, false
}

// ShapeCapture is ShapeSingle for a capture or a recovered expression, whose value is the unit
// node of the range matched when the expression has no value.
func (p *Parser) ShapeCapture(s Shaper, v *core.Node, start int) *core.Node {
	v, ok := p.ShapeSingle(s, v, start)
	if !ok {
		v = p.NewNode(Data{Kind: noderep.SeqKind, Start: int32(start), End: int32(p.Pos), Fresh: true})
	}
	return v
}

// ScopeValue returns the value of a scope whose body matched [start, p.Pos) with the result v.
func (p *Parser) ScopeValue(s Shaper, v *core.Node, start int) *core.Node {
	if s.Tuple {
		return p.shapeTuple(s, v, start)
	}
	return s.one(v)
}

// --- Terminals ---

// LiteralText returns source bytes if replacement decoding accepted a shorter
// spelling than the literal, retaining the usual constant-text success path.
func (p *Parser) LiteralText(start int, text string) string {
	if p.unit == core.Bytes && p.Pos-start != len(text) {
		return p.Text(start, p.Pos)
	}
	return text
}

func (p *Parser) MatchLiteral(rs []rune, text string, desc ExpID, build bool) (*core.Node, bool) {
	if p.Stream != nil {
		return p.streamMatchLiteral(rs, text, desc, build)
	}
	start := p.Pos
	if p.unit == core.Bytes {
		if !p.hasLiteralPrefix(text) {
			if p.Document != nil {
				p.documentTouchLiteral(text)
			}
			return p.matchReplacementLiteral(rs, text, desc, build)
		}
		p.Pos += len(text)
	} else {
		for _, r := range rs {
			p.SpendRead(1)
			if p.Pos >= p.n || p.In[p.Pos] != r {
				p.documentTouch(p.Pos + 1)
				p.Expect(start, desc)
				return nil, false
			}
			p.Pos++
		}
	}
	p.documentTouch(p.Pos)
	if !build {
		return nil, true
	}
	return p.NewNode(Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: p.LiteralText(start, text), Terminal: true, Fresh: true}), true
}

// MatchLiteralFold is MatchLiteral for a case-insensitive literal. rs is the literal with each ASCII
// letter lowercased, and each input character is folded the same way before it is compared, so
// only ASCII letters ignore case. The node text is the consumed input. Peek records the examined
// characters and the work of each one, so the loop needs no bookkeeping of its own.
func (p *Parser) MatchLiteralFold(rs []rune, desc ExpID, build bool) (*core.Node, bool) {
	start := p.Pos
	for _, want := range rs {
		got, size, ok := p.Peek()
		if !ok || foldASCIIRune(got) != want {
			p.Expect(start, desc)
			return nil, false
		}
		p.Pos += size
	}
	if !build {
		return nil, true
	}
	return p.NewNode(Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: p.Text(start, p.Pos), Terminal: true, Fresh: true}), true
}

// MatchLiteralFoldOrdinary is MatchLiteralFold in an ordinary parse (ExpectOrdinary).
func (p *Parser) MatchLiteralFoldOrdinary(rs []rune, desc ExpID, build bool) (*core.Node, bool) {
	start := p.Pos
	for _, want := range rs {
		got, size, ok := p.PeekOrdinary()
		if !ok || foldASCIIRune(got) != want {
			p.ExpectOrdinary(start, desc)
			return nil, false
		}
		p.Pos += size
	}
	if !build {
		return nil, true
	}
	return p.NewNodeOrdinary(Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: p.Text(start, p.Pos), Terminal: true, Fresh: true}), true
}

// foldASCIIRune maps A-Z to a-z and leaves every other rune as it is.
func foldASCIIRune(r rune) rune {
	if 'A' <= r && r <= 'Z' {
		return r + ('a' - 'A')
	}
	return r
}

// matchReplacementLiteral is the cold path for raw-byte mismatches. An
// invalid input byte and valid U+FFFD decode alike, but occupy different sizes.
func (p *Parser) matchReplacementLiteral(rs []rune, text string, desc ExpID, build bool) (*core.Node, bool) {
	start := p.Pos
	if !p.literalHasReplacement(rs) {
		p.Expect(start, desc)
		return nil, false
	}
	for _, want := range rs {
		got, size, ok := p.Peek()
		if !ok || got != want {
			p.Expect(start, desc)
			return nil, false
		}
		p.Pos += size
	}
	if !build {
		return nil, true
	}
	return p.NewNode(Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: p.LiteralText(start, text), Terminal: true, Fresh: true}), true
}

// MatchLiteralOrdinary is MatchLiteral in an ordinary parse (ExpectOrdinary).
func (p *Parser) MatchLiteralOrdinary(rs []rune, text string, desc ExpID, build bool) (*core.Node, bool) {
	if p.Stream != nil {
		return p.streamMatchLiteral(rs, text, desc, build)
	}
	start := p.Pos
	if p.unit == core.Bytes {
		if !strings.HasPrefix(p.bs[p.Pos:], text) {
			return p.matchReplacementLiteral(rs, text, desc, build)
		}
		p.Pos += len(text)
	} else {
		for _, r := range rs {
			if p.Pos >= p.n || p.In[p.Pos] != r {
				p.ExpectOrdinary(start, desc)
				return nil, false
			}
			p.Pos++
		}
	}
	if !build {
		return nil, true
	}
	return p.NewNodeOrdinary(Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: p.LiteralText(start, text), Terminal: true, Fresh: true}), true
}

// MatchAnyOrdinary is MatchAny in an ordinary parse (ExpectOrdinary).
func (p *Parser) MatchAnyOrdinary(build bool) (*core.Node, bool) {
	_, size, ok := p.PeekOrdinary()
	if !ok {
		p.ExpectOrdinary(p.Pos, IdAny)
		return nil, false
	}
	return p.Single(size, build)
}

func (p *Parser) MatchAny(build bool) (*core.Node, bool) {
	_, size, ok := p.Peek()
	if !ok {
		p.Expect(p.Pos, IdAny)
		return nil, false
	}
	return p.Single(size, build)
}

// Single consumes one character of size units.
func (p *Parser) Single(size int, build bool) (*core.Node, bool) {
	start := p.Pos
	p.Pos += size
	if !build {
		return nil, true
	}
	return p.NewNode(Data{Kind: noderep.MatchKind, Start: int32(start), End: int32(p.Pos), Text: p.Text(start, p.Pos), Terminal: true, Fresh: true}), true
}

func (p *Parser) Anchor(ok bool, desc ExpID) (*core.Node, bool) {
	if ok {
		return nil, true
	}
	p.Expect(p.Pos, desc)
	return nil, false
}

func (p *Parser) AtLineStart() bool {
	p.documentTouchLine()
	if p.Stream != nil {
		return p.streamAtLineStart()
	}
	if p.Pos == 0 {
		return true
	}
	if p.unit == core.Bytes {
		return p.bs[p.Pos-1] == '\n'
	}
	return p.In[p.Pos-1] == '\n'
}

// AtLineStartOrdinary is AtLineStart in an ordinary parse (ExpectOrdinary).
func (p *Parser) AtLineStartOrdinary() bool {
	if p.Stream != nil {
		return p.streamAtLineStart()
	}
	if p.Pos == 0 {
		return true
	}
	if p.unit == core.Bytes {
		return p.bs[p.Pos-1] == '\n'
	}
	return p.In[p.Pos-1] == '\n'
}

// AtLineEndOrdinary is AtLineEnd in an ordinary parse (ExpectOrdinary).
func (p *Parser) AtLineEndOrdinary() bool {
	ch, _, ok := p.PeekOrdinary()
	return !ok || ch == '\n' || ch == '\r'
}

// AtEndOrdinary is AtEnd in an ordinary parse (ExpectOrdinary).
func (p *Parser) AtEndOrdinary() bool {
	if p.Stream != nil {
		return p.streamAtEnd()
	}
	return p.Pos == p.n
}

func (p *Parser) AtLineEnd() bool {
	ch, _, ok := p.Peek()
	return !ok || ch == '\n' || ch == '\r'
}

func (p *Parser) AtEnd() bool {
	p.documentTouch(p.Pos + 1)
	if p.Stream != nil {
		return p.streamAtEnd()
	}
	return p.Pos == p.n
}

// AtEndBatch, AtLineStartBatch and their Ordinary forms are AtEnd and AtLineStart for the parsers
// that cannot stream (no ParseStream); small enough to inline.
func (p *Parser) AtEndBatch() bool {
	p.documentTouch(p.Pos + 1)
	return p.Pos == p.n
}

// AtEndBatchOrdinary is AtEndBatch in an ordinary parse (ExpectOrdinary).
func (p *Parser) AtEndBatchOrdinary() bool {
	return p.Pos == p.n
}

func (p *Parser) AtLineStartBatch() bool {
	p.documentTouchLine()
	if p.Pos == 0 {
		return true
	}
	if p.unit == core.Bytes {
		return p.bs[p.Pos-1] == '\n'
	}
	return p.In[p.Pos-1] == '\n'
}

// AtLineStartBatchOrdinary is AtLineStartBatch in an ordinary parse (ExpectOrdinary).
func (p *Parser) AtLineStartBatchOrdinary() bool {
	if p.Pos == 0 {
		return true
	}
	if p.unit == core.Bytes {
		return p.bs[p.Pos-1] == '\n'
	}
	return p.In[p.Pos-1] == '\n'
}

// --- Attributes ---

type matcher = func(p *Parser) (*core.Node, bool)

// tracked runs m with a separate expectation record and returns its farthest position and
// expectations (valid only until the next record; see unisolate).
func (p *Parser) tracked(m matcher) (v *core.Node, ok bool, far int, expected []ExpID) {
	mark := p.Isolate(p.Pos)
	v, ok = m(p)
	far, expected = p.Unisolate(mark)
	return v, ok, far, expected
}

// ErrorAttr replaces the expectations of a failing m with the message msg (an ID with MsgBit),
// reported at the farthest position m reached.
func (p *Parser) ErrorAttr(m matcher, msg ExpID) (*core.Node, bool) {
	v, ok, far, expected := p.tracked(m)
	if ok {
		p.MergeExpected(far, expected)
		return v, true
	}
	p.Expect(far, msg)
	return nil, false
}

func (p *Parser) DiagnosticAttr(m matcher, name ExpID) (*core.Node, bool) {
	v, ok, far, expected := p.tracked(m)
	if ok {
		p.MergeExpected(far, expected)
		return v, true
	}
	p.MergeExpected(far, RenamedExpected(p, expected, name))
	return nil, false
}

// RenamedExpected is for generated parsers; not a stable API.
func RenamedExpected(p *Parser, expected []ExpID, name ExpID) []ExpID {
	// The isolated record is no longer in the active expectation stack. Charge
	// each conversion and reuse its storage before MergeExpected appends to it.
	for i, id := range expected {
		p.Spend()
		if id&MsgBit == 0 {
			expected[i] = name
		}
	}
	return expected
}

// RecoverAttr records the error of a failing m, skips what skip matches and returns an Error
// node. It fails without recovering when skip fails or skips nothing.
func (p *Parser) RecoverAttr(m, skip matcher, build bool) (*core.Node, bool) {
	m0 := p.Mark()
	v, ok, far, expected := p.tracked(m)
	if ok {
		p.MergeExpected(far, expected)
		return v, true
	}
	expected = p.Keep(expected) // keep them while skipping
	p.Reset(m0)
	if _, ok := skip(p); !ok || p.Pos == m0.Pos {
		p.Reset(m0)
		p.MergeExpected(far, expected)
		return nil, false
	}
	e := p.MakeError(far, expected)
	p.PushRecovered(e)
	if !build {
		return nil, true
	}
	return p.NewErrorNode(m0.Pos, e), true
}

// NewErrorNode returns the node that stands for the input from start to the current position, which a
// recovery (#recover) skipped after the syntax error e: an error node with the message of e, allocated like
// NewNode.
//
// NewErrorNode is for generated parsers; not a stable API.
func (p *Parser) NewErrorNode(start int, e *core.SyntaxError) *core.Node {
	return p.NewNode(Data{Kind: noderep.ErrorKind, Start: int32(start), End: int32(p.Pos), Fields: noderep.Fields{{Name: "message", Value: p.RecoveryErrorText(e)}}, Fresh: true, Terminal: true})
}

// --- Actions and predicates ---

// evalError is the failure of a term, which the compositions return as a value. It fails the whole
// parse in an action and makes a predicate fail.
type evalError struct{ msg string }

// ActCtx is the context of evaluating an action or a predicate.
//
// ActCtx is for generated parsers; not a stable API.
type ActCtx struct {
	P            *Parser
	f            *CaptureFrame
	start, end   int
	cbase        int // start of p.Created made by this evaluation
	Lhs, Rhs, Op any
	Value        any // the folded value of an Operators Rule, in its whole-rule action
}

// UseCtx places the evaluation context in the parser's single context and returns it.
// Evaluations never nest, and no reference to the context survives one (function values
// cannot be stored in fields or variables), so one context per parser can be reused.
func (p *Parser) useCtx(c ActCtx) *ActCtx {
	p.ac = c
	return &p.ac
}

func (c *ActCtx) result(action func(*ActCtx) (any, any), where string) (n *core.Node) {
	defer c.P.dropCreated(c.cbase)
	v, f := action(c)
	if f != nil {
		c.P.actionFailed(where, f)
	}
	if v == nil {
		return nil
	}
	n, ok := v.(*core.Node)
	if !ok {
		if _, isFn := v.(func(...any) any); isFn {
			c.P.actionFailed(where, c.P.evalErrorValue("result must be a value, got a function"))
		}
		// A value other than a node travels boxed, with the range of the action's input.
		return c.P.NewNode(Data{Kind: noderep.BoxKind, Box: v, Start: int32(c.start), End: int32(c.end)})
	}
	for _, x := range c.P.created[c.cbase:] {
		c.P.Spend()
		if x == n {
			D(n).Start, D(n).End = int32(c.start), int32(c.end)
			break
		}
	}
	if n != nil {
		D(n).Fresh = false // the value of an action is final (see the engine's actionResult)
	}
	return n
}

// dropCreated releases tracking references without changing the created values.
func (p *Parser) dropCreated(base int) {
	clear(p.created[base:])
	p.created = p.created[:base]
}

// evalTerm is the operation term.eval: it reports false for a term that fails. A panic, an
// interruption among them, ends the parse and passes through.
func (p *Parser) evalTerm(t func(*ActCtx) (any, any)) (v any, ok bool) {
	v, f := t(p.useCtx(ActCtx{P: p, f: p.Frame, start: p.Pos, end: p.Pos, cbase: len(p.created)}))
	return v, f == nil
}

// actionFailed ends the parse with the failure f of the action in where.
func (p *Parser) actionFailed(where string, f any) {
	panic(fatal{p.wrapEvalError(where, f.(evalError).msg)})
}

// isFalse is the operation term.isFalse.
func isFalse(v any) bool {
	b, isBool := v.(bool)
	return isBool && !b
}

// isFunction is the operation term.isFunction.
func isFunction(v any) bool {
	_, isFn := v.(func(...any) any)
	return isFn
}

func (c *ActCtx) Cap(slot int) any { return UnboxNode(c.f.Vals[slot]) }

// Var returns the value of the variable in slot i.
func (c *ActCtx) Var(slot int) any { return c.P.variable(slot) }

func typeName(v any) string {
	switch v := v.(type) {
	case nil:
		return "nil"
	case *core.Node:
		if v == nil {
			return "nil"
		}
		if D(v).Kind == noderep.BoxKind {
			return typeName(D(v).Box)
		}
		if D(v).Kind.IsNodeType() {
			return v.Type()
		}
		return valueTypeName(shape(v), v.Type(), len(D(v).Children))
	case int:
		return "int"
	case string:
		return "string"
	case bool:
		return "bool"
	}
	return fmt.Sprintf("%T", v)
}

// TermStruct returns a new struct of the type typ with no field set and an empty range, with room for
// n fields: the operation term.struct of a term that makes a struct.
//
// TermStruct is for generated parsers; not a stable API.
func (c *ActCtx) TermStruct(typ string, n int) *core.Node {
	k := c.P.g.TypeKinds[typ]
	if k == nil {
		k = KindOf(typ, "")
	}
	return c.P.NewNode(Data{Kind: k, Fields: c.P.fields(n)})
}

// TermSetField sets the field name of the struct n, which a term is making, to v: the operation
// term.setField.
//
// TermSetField is for generated parsers; not a stable API.
func (c *ActCtx) TermSetField(n *core.Node, name string, v any) {
	c.P.setValueField(&D(n).Fields, name, v)
}

func (c *ActCtx) NewList(items []*core.Node) *core.Node {
	kids := c.P.Nodes(len(items))
	copySpend(c.P, kids, items)
	return c.listNode(kids)
}

// listNode returns a list value with the child list kids (which it takes over). Its range, which
// the value model does not show, covers the elements that are nodes.
func (c *ActCtx) listNode(kids []*core.Node) *core.Node { return c.P.TermHull(c, false, kids) }

// TOperand is an operand of a comparison: a string field read without boxing it (Str, with
// IsStr), or any other value (V).
//
// TOperand is for generated parsers; not a stable API.
type TOperand struct {
	V     any
	Str   string
	IsStr bool
}

func (o TOperand) value() any {
	if o.IsStr && o.V == nil {
		return o.Str
	}
	return o.V
}

// memberZero is the operation node.zero: the zero value of the declared type of the field name of the
// struct n, and false if its type declares no such field.
func (p *Parser) memberZero(c *ActCtx, n *core.Node, name string) (any, bool) {
	zero, ok := p.g.StructFields[n.Type()].zeros[name]
	if !ok {
		return nil, false
	}
	v, _ := c.zeroValue(zero)
	return v, true
}

// zeroValue builds the zero value that the descriptor d describes and returns it with the rest of d.
func (c *ActCtx) zeroValue(d string) (any, string) {
	if d == "" {
		return nil, d
	}
	switch d[0] {
	case 'i':
		return 0, d[1:]
	case 's':
		return "", d[1:]
	case 'b':
		return false, d[1:]
	case 'l':
		return c.listNode(c.P.Kids(len(c.P.KidStack))), d[1:]
	case '(':
		base := len(c.P.KidStack)
		d = d[1:]
		for d != "" && d[0] != ')' {
			var e any
			e, d = c.zeroValue(d)
			c.P.Spend()
			if f := c.P.TermPush(c, "tuple", e); f != nil {
				panic("runtime: a zero value is not a tuple element") // zero values are never functions
			}
		}
		return c.P.TermHull(c, true, c.P.Kids(base)), strings.TrimPrefix(d, ")")
	case '{':
		// The zero value of a struct type is a struct with no field set, whose fields read as their own
		// zero values, so that making it costs the same whatever the type holds.
		name, rest, _ := strings.Cut(d[1:], "}")
		n := c.TermStruct(name, 0)
		c.P.TermMade(c, n, true)
		return n, rest
	}
	return nil, d[1:]
}

// --- Operators Rule expressions ---

// OperatorsRule is for generated parsers; not a stable API.
type OperatorsRule struct {
	Skip     matcher
	Operands []*OperatorsRuleLine
	Prefix   []*OperatorsRuleOp
	Led      []*OperatorsRuleOp
}

// OperatorsRuleLine is for generated parsers; not a stable API.
type OperatorsRuleLine struct {
	Scope  []string
	M      matcher
	Action func(*ActCtx) (any, any)
	// Value makes the value of an operand line without an action, and of an operator line's
	// operator, from the value of the line's expression.
	Value Shaper
}

// OperatorsRuleOp is for generated parsers; not a stable API.
type OperatorsRuleOp struct {
	Id    int
	Kind  string
	Assoc string
	Level int
	Line  *OperatorsRuleLine
}

type operatorsRuleAttempt struct {
	op         *OperatorsRuleOp
	frame      *CaptureFrame
	v          *core.Node
	start, end int
	env        *Env
	cut        bool
	errs       recEntry
}

func (p *Parser) lineResult(r *Rule, l *OperatorsRuleLine, f *CaptureFrame, v *core.Node, start int) *core.Node {
	if r.Novalue {
		return nil
	}
	return p.lineValue(r, l, f, v, start)
}

func (p *Parser) lineValue(r *Rule, l *OperatorsRuleLine, f *CaptureFrame, v *core.Node, start int) *core.Node {
	if l.Action != nil {
		c := p.useCtx(ActCtx{P: p, f: f, start: start, end: p.Pos, cbase: len(p.created)})
		return c.result(l.Action, r.where())
	}
	v = p.ScopeValue(l.Value, v, start)
	if len(l.Scope) > 0 {
		v = p.AttachCaptures(v, l.Scope, f, start, p.Pos)
	}
	if v != nil && D(v).Fresh {
		if p.sourceInfo && D(v).Kind.Rule == "" {
			D(v).Kind = r.kinds.Named(D(v).Kind, r.Name)
		}
		D(v).Fresh = false
	}
	return v
}

// convertOperator converts v, the value of an operator of rule r, to the named node type of the
// rule's operators.
func (p *Parser) convertOperator(r *Rule, v *core.Node) *core.Node {
	n, ok := r.opKinds.convert(UnboxNode(v))
	if !ok {
		panic(fatal{fmt.Errorf("cannot convert %s to %s in result of rule %s", typeName(UnboxNode(v)), r.OpNodeType, r.where())})
	}
	return n
}

func (p *Parser) operatorsRuleBuild(r *Rule, a *operatorsRuleAttempt, lhs, rhs *core.Node) *core.Node {
	if r.Novalue {
		return nil
	}
	start, end := a.start, p.Pos
	if lhs != nil {
		start = int(D(lhs).Start)
	}
	if a.op.Kind == "postfix" {
		end = a.end
	}
	l := a.op.Line
	// The operator's value is its one element, or the node of its tuple, which has the line's
	// captures.
	opv, ok := p.ShapeSingle(l.Value, a.v, a.start)
	if !ok {
		opv = p.NewNode(Data{Kind: noderep.SeqKind, Start: int32(a.start), End: int32(a.end)})
	}
	if l.Value.Mode == singleTuple && len(l.Scope) > 0 {
		opv = p.AttachCaptures(opv, l.Scope, a.frame, a.start, a.end)
	}
	if opv != nil {
		D(opv).Fresh = false
	}
	if l.Action != nil {
		c := p.useCtx(ActCtx{P: p, f: a.frame, start: start, end: end, cbase: len(p.created),
			Op: UnboxNode(opv), Lhs: UnboxNode(lhs), Rhs: UnboxNode(rhs)})
		v := c.result(l.Action, r.where())
		if r.opKinds != nil {
			v = p.convertOperator(r, v)
		}
		return v
	}
	// Without an action, the application is the node of the tuple (lhs, op, rhs) of the line's
	// kind, with those captures.
	var kids []*core.Node
	var fields noderep.Fields
	switch a.op.Kind {
	case "prefix":
		kids = p.Nodes(2)
		kids[0], kids[1] = opv, rhs
		fields = noderep.Fields{{Name: "op", Value: nodeOrNil(opv)}, {Name: "rhs", Value: nodeOrNil(rhs)}}
	case "postfix":
		kids = p.Nodes(2)
		kids[0], kids[1] = lhs, opv
		fields = noderep.Fields{{Name: "lhs", Value: nodeOrNil(lhs)}, {Name: "op", Value: nodeOrNil(opv)}}
	default:
		kids = p.Nodes(3)
		kids[0], kids[1], kids[2] = lhs, opv, rhs
		fields = noderep.Fields{{Name: "lhs", Value: nodeOrNil(lhs)}, {Name: "op", Value: nodeOrNil(opv)}, {Name: "rhs", Value: nodeOrNil(rhs)}}
	}
	kind := noderep.SeqKind
	if r.opKinds != nil {
		kind = r.opKinds[noderep.BaseTuple] // made with the named node type of the operators
	} else if p.sourceInfo {
		kind = r.kinds.Named(noderep.SeqKind, r.Name)
	}
	n := p.NewNode(Data{Kind: kind, Start: int32(start), End: int32(end), Children: kids, Fields: fields, Labeled: p.sourceInfo})
	return n
}

